INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$A. B. M. Musa$b$, DATE '1931-03-08', DATE '2014-04-09', $b$A B M Musa (28 February 1931 – 9 April 2014) was a Bengali journalist. He was the chief editor of Bangladesh Sangbad Sangstha (BSS). He was awarded Ekushey Padak for journalism in 1999 by the government of Bangladesh.

Awards: Ekushey Padak, Honorary Fellow of Bangla Academy
Education: Comilla Victoria Government College, Noakhali Zilla School

Source: Wikipedia — https://en.wikipedia.org/wiki/A._B._M._Musa$b$, 'en', NULL, $b$Journalist, Politician$b$, NULL, $b$Dhaka$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$A. H. M. Moazzem Hossain$b$, DATE '1948-01-01', DATE '2018-08-02', $b$A. H. M. Moazzem Hossain (1 January 1948 – 2 August 2018) was a Bangladeshi journalist and editor. He was best known as the founding editor of The Financial Express, a leading English-language daily focused on business and finance.

Source: Wikipedia — https://en.wikipedia.org/wiki/A._H._M._Moazzem_Hossain$b$, 'en', NULL, $b$Journalist, Newspaper editor$b$, NULL, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$A. K. A. Firoze Noon$b$, DATE '1946-01-04', DATE '2006-12-23', $b$A. K. A. Firoze Noon (4 January 1946 – 23 December 2006)  was a Bangladeshi politician and one of the founding members of the Bangladesh Nationalist Party (BNP). He was also a founding professor of the BNP's political training centre and the party's former political and economic research editor. During the First Khaleda ministry, he served as a political adviser to Prime Minister Khaleda Zia.

Education: Govt. Brajalal College

Source: Wikipedia — https://en.wikipedia.org/wiki/A._K._A._Firoze_Noon$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Firoze%20Noon%20and%20Dilip%20Kumar%20%28cropped%29.jpg?width=640$b$, $b$Writer, Politician$b$, NULL, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$A. N. M. Momtaz Uddin Choudhury$b$, DATE '1923-01-01', DATE '2005-10-02', $b$A. N. M. Momtaz Uddin Chowdhury (1923 – 2 October 2005) was a Bangladeshi writer and academic. He was the first vice-chancellor (1981–1988) of Islamic University, Bangladesh. He also served as project director for establishing Islamic University, Bangladesh. He also served as the director general of the Directorate of Secondary and Higher Education in 1963.

Source: Wikipedia — https://en.wikipedia.org/wiki/A._N._M._Momtaz_Uddin_Choudhury$b$, 'en', NULL, $b$Writer, Academic$b$, $b$Lakshmipur Sadar Upazila$b$, NULL, 'year', 'day');
