INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$AKM Yusuf$b$, DATE '1926-03-01', DATE '2014-02-09', $b$Abul Kalam Muhammad Yusuf was a Bangladeshi Islamic scholar, hadith expert, translator, author, farmer organizer, and politician.

He served as chairman of the Bangladesh Farmers Welfare Association and as Naib-e-Ameer of the Bangladesh Jamaat-e-Islami. The International Crimes Tribunal indicted him for alleged involvement in crimes against humanity during the Bangladesh Liberation War in 1971. The prosecution at the tribunal charged him with 13 counts. He died in a hospital in February 2014 while receiving treatment in prison custody.

Source: Wikipedia — https://en.wikipedia.org/wiki/AKM_Yusuf$b$, 'en', NULL, $b$Writer, Politician$b$, $b$Bagerhat Sadar Upazila$b$, $b$Bangladesh Medical University$b$, 'month', 'day');
