INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abdul Hakim$b$, DATE '1905-01-01', DATE '1985-06-14', $b$Khan Bahadur Abdul Hakim CIE (Bengali: খান বাহাদুর আব্দুল হেকীম; 2 December 1905 – 14 June 1985) was a Bangladeshi educationist, mathematician and writer. He was the former Dhaka Division school inspector. He was awarded both Khan Sahib and Khan Bahadur by the British Raj. He later served as the president of the Asiatic Society of Bangladesh and established its first scholarship endowment.

