INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abdul Hakim Sarkar$b$, NULL, DATE '2016-06-30', $b$Abdul Hakim Sarkar (died 11 May 2025) was a Bangladeshi writer, academic, and professor. He was the 11th vice chancellor (27 December 2012 – 30 June 2016) of Islamic University, Bangladesh. He was a long time professor of Dhaka University at Social welfare and research institute.

