INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abdul Halim Bukhari$b$, DATE '1945-01-01', DATE '2022-06-21', $b$Abdul Halim Bukhari (Bengali: আব্দুল হালিম বুখারী; January 1945 – 21 June 2022) was a Bangladeshi Islamic scholar, educator, and writer who was the director general of Al Jamia Al Islamia Patiya from 2008 until his death. He held the position of secretary general of Anjuman-e-Ittihadul Madaris Bangladesh from 1983, and from 2018, he served as an ex-officio standing committee member of Al-Haiatul Ulya Lil-Jamiatil Qawmia Bangladesh, the government-recognized apex body overseeing Qawmi madrasas. He also served as an advisor to Hefazat-e-Islam Bangladesh, member of Bangladesh Qawmi Madrasa Education Commission, chaired the Shariah Supervisory Committee of Shahjalal Islami Bank, and was president of both the Organization of Islamic Conference Bangladesh and the Organization of Tahfizul Quran Bangladesh. In addition to his educational and organizational roles, he was the editor-in-chief of Monthly At-Tawhid, a religious periodical published in Chittagong.

Education: University of Dhaka, Al Jamia Al Islamia Patiya

Source: Wikipedia — https://en.wikipedia.org/wiki/Abdul_Halim_Bukhari$b$, 'en', NULL, $b$Writer, Ulema$b$, $b$Lohagara Upazila$b$, NULL, 'month', 'day');
