INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abdul Haque Faridi$b$, DATE '1903-01-01', DATE '1996-02-05', $b$Abul Faraḥ Muḥammad Abdul Ḥaque Farīdī (25 May 1903 – 5 February 1996) was a Bangladeshi educator and author. In recognition of his contributions in the field of linguistics, he was awarded a Bangla Academy Fellowship. Faridi was the founder of Islamic Foundation Bangladesh's Islami Bishwakosh (Islamic encyclopedia) project and also worked closely with Bangladesh Scouts.

Education: University of Illinois System, University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Abdul_Haque_Faridi$b$, 'en', NULL, $b$Writer$b$, $b$Faridpur District$b$, NULL, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abdul Hye Mashreki$b$, DATE '1909-04-01', DATE '1988-12-04', $b$Abdul Hye Mashreki (1 April 1919 – 4 December 1988) was a Bangladeshi folk litterateur and poet. He is known for his writing in the 1930s and 1940s. He mainly focused the lifestyle of the rural people of Bengal. Some notable works of him include Rakhal Bondhu, Jarina Sundari, Allah Megh De Chaya De, Fande Poriya Boga Kande Re, Amar Kakher Kolshi, He Amar Desh and Kichu Rekhe Jete Chai.

Mashreki wrote against the social, economical, religious and racial discrimination in the rural area. Mihir Acarya, researcher of Bengali literature named three main folk poets – Mashreki, Jasimuddin and Bande Ali Mia – in his research in the time period of 1917 to 1936.

Education: Ishwarganj Bisweswari Pilot High School

Source: Wikipedia — https://en.wikipedia.org/wiki/Abdul_Hye_Mashreki$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/%E0%A6%95%E0%A6%AC%E0%A6%BF%20%E0%A6%86%E0%A6%AC%E0%A6%A6%E0%A7%81%E0%A6%B2%20%E0%A6%B9%E0%A6%BE%E0%A6%87%20%E0%A6%AE%E0%A6%BE%E0%A6%B6%E0%A6%B0%E0%A7%87%E0%A6%95%E0%A7%80.jpg?width=640$b$, $b$Literary scholar, Writer$b$, $b$Ishwarganj Upazila$b$, $b$Ishwarganj Upazila$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abdul Khaleque$b$, DATE '1892-01-01', DATE '1955-04-02', $b$Abdul Khaleque was a social reformer, Islamic preacher, educator, philosopher, Sufi personality, politician, and writer. He was born in 1892 in the village of Chhatura, in the Tipperah District of Bengal Presidency, British India (now in Akhaura Upazila, Brahmanbaria District, Bangladesh).

Notable works: Sayyedul Mursaleen
Education: University of Dhaka, Comilla Victoria Government College, Ishwar Pathshala

Source: Wikipedia — https://en.wikipedia.org/wiki/Abdul_Khaleque_(scholar)$b$, 'en', NULL, $b$Ulema, Murshid, Politician, Writer, Translator$b$, $b$Akhaura Upazila$b$, $b$Dhaka$b$, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abdul Latif Chowdhury Fultali$b$, DATE '1913-05-25', DATE '2008-01-16', $b$Abdul Latif Chowdhury Fultali (Bengali: আব্দুল লতিফ চৌধুরী ফুলতলী; 25 May 1913 – 16 January 2008), reverentially known as Saheb Qiblah, was a late-twentieth-century Bangladeshi Islamic scholar, mufassir, qāriʾ, poet and orator. As a prolific author, he completed several works in Arabic, Bengali and Urdu including Muntakhab as-Siyār and Anwar as-Sālikīn. His books are part of syllabic studies under the Bangladesh Madrasah Education Board. Fultali was the leading figure of the Islamic Arabic University movement and the demand for fazil and kamil qualifications to be recognized as bachelor's and master's degrees. He is the founder of several influential organisations and institutions in Bangladesh and the United Kingdom such as Anjumane Al Islah, Hazrat Shahjalal Darussunnah Yaqubia Kamil Madrasa and Madrasah-e-Darul Qirat Majidiah.

He was the founder of Darul Hadis Latifiah In London, one of the oldest private Islamic institutes.

Source: Wikipedia — https://en.wikipedia.org/wiki/Abdul_Latif_Chowdhury_Fultali$b$, 'en', NULL, $b$Writer, Theologian$b$, $b$Zakiganj Upazila$b$, $b$Sylhet Division$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abdul Mannan$b$, DATE '1935-03-09', DATE '2006-02-06', $b$Abdul Mannan (9 March 1935 – 6 February 2006) was a Bangladeshi religious leader and journalist who served as the minister for religious affairs in the cabinet of Hussain Muhammad Ershad. He was the founder of Daily Inqilab. He was accused of being a collaborator of the Pakistan Army and was accused of war crimes during the Bangladesh Liberation War.

Source: Wikipedia — https://en.wikipedia.org/wiki/Abdul_Mannan_(Chandpur_politician)$b$, 'en', NULL, $b$Journalist$b$, NULL, $b$Dhaka$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abdul Quadir$b$, DATE '1906-06-01', DATE '1984-12-19', $b$Abdul Quadir (1 June 1906 – 19 December 1984) was a Bangladeshi poet, essayist, and journalist. He was the recipient of the Bangla Academy Literary Award in 1963 and the Ekushey Padak in 1976.

Awards: Ekushey Padak, Independence Award in Literature, Bangla Academy Literary Award
