INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abdul Wahhab Pirji$b$, DATE '1895-01-01', DATE '1976-09-29', $b$Abdul Wahhab Pirji (Bengali: আব্দুল ওহাব পীরজী; 1890 – 29 September 1976), popularly referred to as Pirji Huzur (Bengali: পীরজী হুজূর), was a Bangladeshi Islamic scholar, author and educationist. He was a disciple of Ashraf Ali Thanwi and the founding principal of Jamia Hussainia Ashraful Uloom in Bara Katara, Dhaka.

