INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abdullah al Mamun$b$, DATE '1942-07-13', DATE '2008-08-21', $b$Abdullah Al Mamun (13 July 1942 – 21 August 2008) was a Bangladeshi playwright, actor, and filmmaker. He earned the Bangla Academy Literary Award in 1978 and the Ekushey Padak in 2000 from the Government of Bangladesh. As a filmmaker, he won Bangladesh National Film Award for Best Director twice for the direction of the films Ekhoni Somoy (1980) and Dui Jibon (1988).

