INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abu Saeed Muhammad Omar Ali$b$, DATE '1945-10-01', DATE '2010-08-14', $b$Abu Saeed Muhammad Omar Ali (Bengali: আবু সাঈদ মুহাম্মদ ওমর আলী; 1 October 1945 — 14 August 2010) was a Bangladeshi Islamic scholar, author, teacher, and translator. As a member of the Islamic Foundation's encyclopedia project's board of directors and editing board, his most notable works are Islami Bishwakosh (25 volumes), Sirat Bishwakosh (14 volumes) and Al-Quran Bishwakosh. He was also the editor of the Hakkatha and Islamic Foundation Magazine. Ali became acquainted with Abul Hasan Ali Hasani Nadwi after translating his books, and later became one of his senior disciples and his principal Bengali commentator.

Education: University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Abu_Saeed_Muhammad_Omar_Ali$b$, 'en', NULL, $b$Writer$b$, NULL, NULL, 'day', 'day');
