Education: University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Abul_Kalam_Mohammed_Zakaria$b$, 'en', NULL, $b$Archaeologist, Writer$b$, $b$Brahmanbaria$b$, $b$Dhaka$b$, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abul Kalam Zakaria$b$, DATE '1956-01-01', DATE '2019-03-11', $b$Abul Kalam Zakaria (15 March 1956 – 11 March 2019), also known as Faqihul Millat, was a Bangladeshi Deobandi Islamic scholar, jurist, and educationist. He was the principal and the Grand Mufti of Jamea Qasimul Uloom Dargah Hazrat Shah Jalal Sylhet and editor of the monthly magazine al-Qasim. In the greater Sylhet region, he made unique and extraordinary contributions to the religious, educational, and various other social activities.

Source: Wikipedia — https://en.wikipedia.org/wiki/Abul_Kalam_Zakaria$b$, 'en', NULL, $b$Writer$b$, NULL, NULL, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Abul Kashem Sandwip$b$, DATE '1944-04-01', DATE '1995-12-10', $b$Abul Kashem Sandwip (1 April 1944 – 10 December 1995) was a Bangladeshi educationist, journalist and organizer. He is one of the founders of Bangladesh Betar, the national radio service of Bangladesh. He is the second person to read the declaration of the Independence of Bangladesh from the radio.

