INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Adwaita Mallabarman$b$, DATE '1914-01-01', DATE '1951-04-16', $b$Adwaita Mallabarman (also spelled Advaita; 1 January 1914 – 16 April 1951) was a Bengali writer and journalist based in India. Today, he is best known for the novel, Titas Ekti Nadir Naam (A River Called Titas), which was published posthumously in 1956, following his death in 1951. He was briefly associated with Anandabazar Patrika, Yugantar and Desh.

Notable works: Titas Ekti Nadir Nam
Education: Comilla Victoria Government College, Annada Government High School

