INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Alam Khan$b$, DATE '1944-10-22', DATE '2022-07-08', $b$Alam Khan (22 October 1943 – 8 July 2022) was a Bangladeshi composer and music director. He was awarded Bangladesh National Film Award for Best Music Director five times for the films Boro Bhalo Lok Chhilo (2005), Teen Kanya (2006), Surrender (2007), Dinkal (2008) and Ibadat (2009). He also won Best Music Composer Award for the films Bagher Thaba (2005) and Ki Jadu Korila (2008). As of 2008, Khan composed around 2000 songs and provided music direction to around 300 films. He is notable for the composition of the songs "Ore Neel Doriya Amay De Re De Chhariya", "Ami Rajanigandha", "Daak Diachhe Doyal Amarey", "Hayre Manush Rangin Phanush" and "Tumi Jekhaney Ami Shekhaney".

Awards: Bangladesh National Film Awards

Source: Wikipedia — https://en.wikipedia.org/wiki/Alam_Khan_(composer)$b$, 'en', NULL, $b$Lyricist, Composer$b$, $b$Sirajganj District$b$, $b$Dhaka$b$, 'day', 'day');
