INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Altaf Husain$b$, DATE '1900-01-26', DATE '1968-05-25', $b$Altaf Husain (Bengali: আলতাফ হোসেইন, Urdu: الطاف حسين; 26 January 1900 – 25 May 1968) was an educationist, journalist, and Pakistan Movement activist. He is noted as one of the pioneers of print journalism in Pakistan and was the founding editor and the first editor-in-chief of English-language newspaper, Dawn, which he edited for almost twenty years.

In addition, he served as Industry Minister of Pakistan in the administration of President Ayub Khan from 1965 until resigning in 1968 for health reasons. He is widely regarded as one of the key activists in the Pakistan Movement and penned several critically important articles in support of the case of Indian Muslims in British Indian Empire. He translated Shikwa and Jawab-e-Shikwa by the poet Muhammad Iqbal from Urdu into rhymed English verse, in 1943.

Education: University of Calcutta, University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Altaf_Husain$b$, 'en', NULL, $b$Journalist, Writer, Philologist$b$, $b$Sylhet$b$, $b$Karachi$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Amala Shankar$b$, DATE '1919-06-27', DATE '2020-07-24', $b$Amala Shankar (née Nandy, 27 June 1919 – 24 July 2020)  was an Indian dancer. She was the wife of dancer and choreographer Uday Shankar and mother of musician Ananda Shankar and dancer  Mamata Shankar (later she became an actress)  and sister-in-law of musician and composer Ravi Shankar. Amala Shankar acted in the film Kalpana written, co-produced and directed by husband Uday Shankar. She died on Friday, 24 July 2020, in West Bengal's Kolkata, India aged 101.

Awards: Banga Bibhushan

Source: Wikipedia — https://en.wikipedia.org/wiki/Amala_Shankar$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Amala%20Shankar%20-%20Kolkata%202011-05-09%202810.JPG?width=640$b$, $b$Dancer, Film actor, Writer$b$, $b$Jashore$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Amalendu De$b$, DATE '1930-01-02', DATE '2014-05-16', $b$Amalendu De (1929–16 May 2014) was Guru Nanak Professor of History at Jadavpur University, where he specialised in the history of the Indian independence movement. He served for some time as president and as secretary of the Asiatic Society and in 1982 was president of the Indian History Congress at its meeting in Aligarh.

