INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Anirvan$b$, DATE '1896-07-08', DATE '1978-05-31', $b$Sri  Anirvan (8 July 1896 – 31 May 1978), born  Narendra Chandra Dhar, was an Indian Hindu monk, writer and philosopher. Widely known as a scholar, his principal works were a Bengali translation of Sri Aurobindo's The Life Divine and the three-volume treatise Veda Mimamsa.

