INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Arjumand Ali$b$, DATE '1870-01-01', DATE '1930-01-01', $b$Arjumand Ali Chowdhury (Bengali: আর্জুমন্দ আলী চৌধুরী; 1870–1930), better known as simply Arjumand Ali, was a blind Bengali author and poet during the British Raj. The customary style of Bengali literature had historically been through poetry (puthis), with prose literature only emerging in the 19th century. Ali's Premdarpaṇ is the earliest example of a prose novel from Bengal's Muslim community.

