INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Ashraf Ali Bishwanathi$b$, DATE '1928-01-01', DATE '2005-05-20', $b$Ashraf Ali Bishwanathi (1928–2005) was a Bangladeshi Deobandi Islamic scholar, educator, politician and religious writer. He was called "Baba-e Jamiat" in order to lay the foundation of Jamiat Ulema-e-Islam Bangladesh in East Pakistan and present day Bangladesh. He was also the president of the party for 2001 to 2005. He was also the founder of Jamia Islamia Darul Uloom Madania Bishwanath, Madania Qawmia Mahila Madrasa and the literary magazine Monthly Al Farooq.

