INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Atiśa$b$, DATE '0982-01-01', DATE '1054-01-01', $b$Atiśa Dīpaṃkara Śrījñāna (c. 982–1054 CE) was a Buddhist religious teacher and leader from Bengal. He is generally associated with his body of work authored at Vikramaśīla Monastery in Bihar. He was a major figure in the spread of 11th-century Mahayana and Vajrayana Buddhism in Asia and traveled to Sumatra and Tibet. Atiśa, along with his chief disciple Dromtön, is regarded as the founder of the Kadam school, one of the New Translation schools of Tibetan Buddhism. In the 14th century, the Kadam school was supplanted by the Gelug tradition, which adopted its teachings and absorbed its monasteries.

Notable works: Bodhipathapradīpa

Source: Wikipedia — https://en.wikipedia.org/wiki/Ati%C5%9Ba$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Atisha.jpg?width=640$b$, $b$Monk, Editor, Writer, Tertön, Translator, Compiler$b$, $b$Bikrampur$b$, $b$Nyêtang$b$, 'year', 'year');
