INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Ayub Ali$b$, DATE '1887-01-01', DATE '1995-01-01', $b$Abū al-Khayr Muḥammad Ayyūb ʿAlī al-Māturīdī (Arabic: أبو الخير محمد أيوب علي الماتريدي; 1919–1995), or simply Ayub Ali (Bengali: আইয়ূব আলী), was a Bangladeshi Islamic scholar, author and educationist. He was awarded the Ekushey Padak in 1976 by the Government of Bangladesh.

