INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Bhupendra Kumar Datta$b$, DATE '1892-10-08', DATE '1979-12-29', $b$Bhupendra Kumar Dutta (Bengali: ভূপেন্দ্র কুমার দত্ত; 8 October 1892 – 29 December 1979) was an Indian freedom fighter and a revolutionary who fought for Indian independence from  British rule. In addition to his other specific contributions as a Jugantar leader, he holds the record of a hunger strike for 78 days in Bilaspur Jail in December 1917.

Education: University of Calcutta, The Sanskrit College and University, Scottish Church College

Source: Wikipedia — https://en.wikipedia.org/wiki/Bhupendra_Kumar_Datta$b$, 'en', NULL, $b$Revolutionary, Writer$b$, $b$Jashore District$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Bibhutibhushan Datta$b$, DATE '1888-06-28', DATE '1958-10-06', $b$Bibhutibhushan Datta (Bengali: বিভূতিভূষণ দত্ত, romanized: Bibhūtibhūṣaṇ Datta; also Bibhuti Bhusan Datta; 28 June 1888 – 6 October 1958) was a historian of Indian mathematics.

Datta came from a poor Bengali family. He was a student of Ganesh Prasad, studied at the University of Calcutta and secured a master's degree in mathematics in 1914 and a doctorate degree in 1920 in applied mathematics. He taught at Calcutta University where he was a lecturer at the University Science College, and from 1924 to 1929 he was the Rhashbehari Ghosh Professor of Applied Mathematics. During the 1920s and 1930s he created a reputation as an authority on the history of Indian mathematics. He was also deeply interested in Indian philosophy and religion. In 1929 he retired from his professorship and left the university in 1933, and became a sannyasin (an ascetic, a person who has renounced worldly pleasures) in 1938 under the name Swami Vidyaranya.

History of Hindu Mathematics: A Source Book, written by him jointly with Avadhesh Narayan Singh (1901–1954) became a standard reference work in the history of Indian mathematics. He also wrote a monograph on the Shulba Sutras. He published more than 70 research papers mostly related to the history of Indian mathematics.

In the last years of his life, as Swami Vidyaranya, he lived mainly at Pushkar, a Hindu holy site in Rajasthan.

Notable works: History of Hindu Mathematics: A Source Book
Education: Presidency University, University of Calcutta

Source: Wikipedia — https://en.wikipedia.org/wiki/Bibhutibhushan_Datta$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Bibhutibhushan%20Datta.jpeg?width=640$b$, $b$Writer, Mathematician, Historian of mathematics, Sannyasi$b$, $b$Chittagong$b$, $b$Pushkar$b$, 'day', 'day');
