INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Bipin Chandra Pal$b$, DATE '1858-11-07', DATE '1932-05-20', $b$Bipin Chandra Pal (Bengali: বিপিন চন্দ্র পাল ; 7 November 1858 – 20 May 1932) was an Indian nationalist, writer, orator, social reformer, and freedom fighter. He was one third of the "Lal Bal Pal" triumvirate. He was one of the main architects of the Swadeshi movement. He is known as the Father of Revolutionary Thoughts in India. He also opposed the partition of Bengal by the British colonial government.

Education: Hindu School, Presidency University, St. Paul's Cathedral Mission College

