INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Bishnu Prasad Rabha$b$, DATE '1909-01-31', DATE '1969-06-20', $b$Bishnu Prasad Rabha (Assamese pronunciation: [bisnu pɹɔxad ɹabʱa]; 31 January 1909 – 20 June 1969) was an Indian cultural figure from Assam, known for his contributions to music, dance, painting, literature, and political activism. As an advocate of the people's cultural movement, he drew heavily from various genres of classical and folk cultural traditions. Considered a doyen of the culture of Assam, the people of Assam affectionately call him Kalaguru (meaning "master of the arts"). He is also called by Marxists Sainik Silpi (sainik "soldier", silpi "artist") for his active participation in the armed struggle led by the Revolutionary Communist Party of India (RCPI).

Education: University of Calcutta, Surendranath College, St. Paul's Cathedral Mission College, Acharya Brojendra Nath Seal College

Source: Wikipedia — https://en.wikipedia.org/wiki/Bishnu_Prasad_Rabha$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Bishnu%20rabha.png?width=640$b$, $b$Songwriter, Poet$b$, $b$Dhaka$b$, $b$Tezpur$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Blanaid Salkeld$b$, DATE '1880-01-01', DATE '1959-12-18', $b$Blánaid Salkeld (born Florence Madeline ffrench–Mullen; 10 August 1880 – 18 December 1959) was a Bengali–born Irish poet, playwright, actor, publisher, salonnière, translator, and reviewer. Salkeld's literary salon was attended by, among others, Patrick Kavanagh and Flann O'Brien.

