INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Buddhadeb Guha$b$, DATE '1936-06-29', DATE '2021-08-29', $b$Buddhadeb Guha (29 June 1936 – 29 August 2021) was an Indian Bengali language fiction writer, singer and painter.

Awards: Ananda Puraskar
Education: University of Calcutta, Barisal Zilla School

Source: Wikipedia — https://en.wikipedia.org/wiki/Buddhadeb_Guha$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Buddhadeb%20Guha%20photo.png?width=640$b$, $b$Writer, Painter, Singer, Artist$b$, $b$Barishal$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Buddhadeva Bose$b$, DATE '1908-11-30', DATE '1974-08-14', $b$Buddhadeva Bose  (Bengali: বুদ্ধদেব বসু;30 November 1908 – 14 August 1974), also spelt Buddhadeb Bosu, was an Indian Bengali writer of the 20th century. Frequently referred to as a poet, he was a versatile writer who wrote novels, short stories, plays and essays in addition to poetry. He was an influential critic and editor of his time. He is recognised as one of the five poets who moved to introduce modernity into Bengali poetry. It is said that since Rabindranath Tagore, there has not been a more versatile talent in Bengali literature.

Awards: Sahitya Akademi Award, Padma Bhushan
Education: University of Dhaka, Dhaka Collegiate School

Source: Wikipedia — https://en.wikipedia.org/wiki/Buddhadeva_Bose$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Buddhadeb%20Bosu%202008%20stamp%20of%20India.jpg?width=640$b$, $b$Poet, Writer$b$, $b$Cumilla District$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Bulbul Chowdhury$b$, DATE '1919-01-01', DATE '1954-05-17', $b$Bulbul Chowdhury (1 January 1919 – 17 May 1954), real name Rashid Ahmed Chowdhury, was a Bengali dancer of British India, and later East Pakistan. He is primarily regarded as a pioneer of modern dance in Bangladesh, as a founding figure of dance among the conservative Muslim community.

Awards: Bangla Academy Literary Award, Pride of Performance, Independence Award
Education: Scottish Church College, University of Calcutta, Manikganj Govt. High School

Source: Wikipedia — https://en.wikipedia.org/wiki/Bulbul_Chowdhury$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/ChowdhuryBulbul.jpg?width=640$b$, $b$Writer, Dancer$b$, $b$Chittagong$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Burhanuddin Khan Jahangir$b$, DATE '1936-01-09', DATE '2020-03-23', $b$Burhanuddin Khan Jahangir (9 January 1936 – 23 March 2020) was a Bangladeshi academic and writer. He was awarded the Bangla Academy Literary Award in 1969 and the Ekushey Padak in 2009.

Awards: Bangla Academy Literary Award, Ekushey Padak
Education: Durham University, University of Dhaka, Dhaka College

Source: Wikipedia — https://en.wikipedia.org/wiki/Burhanuddin_Khan_Jahangir$b$, 'en', NULL, $b$Academic, Writer$b$, NULL, $b$Dhaka$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Chandra Kumar De$b$, DATE '1889-01-01', DATE '1946-01-01', $b$Chandra Kumar De (Bengali: চন্দ্রকুমার দে, romanized: Chôndrôkumar De; 1889–1946) was a writer and collector of medieval folklore and folk ballads of East Bengal villages, mostly in the Greater Mymensingh region which is now in Bangladesh. Today, he is an important folklore collector of Bengal, and his collected ballads are an important part of Bengali folk literature, they were published by University of Calcutta as Moimonshingho Gitika (1923) and Purbabanga Gitika (1923–1932), later published in English as Eastern Bengal Ballads.

Education: University of Calcutta

Source: Wikipedia — https://en.wikipedia.org/wiki/Chandra_Kumar_De$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Chandra%20Kumar%20De.jpg?width=640$b$, $b$Writer$b$, $b$Kendua Upazila$b$, NULL, 'year', 'year');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Chandravati$b$, DATE '1550-01-01', DATE '1600-01-01', $b$Chandrabati (Bengali: চন্দ্রাবতী) was a medieval Bengali poet, widely considered as the first known female poet of Bengali language. She is best known for writing the Bengali version of the ancient epic Ramayana from a woman's perspective.

Source: Wikipedia — https://en.wikipedia.org/wiki/Chandravati_(poet)$b$, 'en', NULL, $b$Poet$b$, $b$Mymensingh$b$, $b$Mymensingh$b$, 'year', 'year');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Chittaranjan Das$b$, DATE '1870-11-05', DATE '1925-06-16', $b$Chittaranjan Das (5 November 1870 – 16 June 1925), popularly called Deshbandhu (friend of the country), was a Bengali freedom fighter, political activist and lawyer during the Indian Independence Movement and mentor of Subhas Chandra Bose. He was the founder-leader of the Swaraj Party in undivided Bengal during the period of British Colonial rule in India. His name is abbreviated as C. R. Das.

He was closely associated with a number of literary societies and wrote poems, apart from numerous articles and essays.

Education: Presidency University

Source: Wikipedia — https://en.wikipedia.org/wiki/Chittaranjan_Das$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Chittaranjan%20Das%203.jpg?width=640$b$, $b$Barrister, Writer, Politician, Freedom fighter, Essayist, Poet$b$, $b$Bikrampur$b$, $b$Step Aside$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Chowara Parameswaran$b$, DATE '1884-06-15', DATE '1968-01-01', $b$Chowara Parameswaran was an Indian journalist, rationalist, reformer, and translator. He is also known as Chowara Gandhi. He participated in the All-Kerala Political Conference held at Palakkad in 1921 and participated in the Vaikom Satyagraha in 1924, the Civil Disobedience Movement in 1930 and the Quit India Movement in 1942. After independence, he worked as a journalist and fought for the rights of journalists. He died on 20 December 1968.

Source: Wikipedia — https://en.wikipedia.org/wiki/Chowara_Parameswaran$b$, 'en', NULL, $b$Journalist, Freedom fighter$b$, $b$Chowara$b$, NULL, 'day', 'year');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Chowdhury Gulam Akbar$b$, DATE '1921-09-16', DATE '1988-12-29', $b$Chowdhury Gulam Akbar (Bengali: চৌধুরী গোলাম আকবর; 16 September 1921 – 29 December 1988) was a Bangladeshi writer. He served in the Bangla Academy of Bangladesh as the collector of Bengali folk literature.

Source: Wikipedia — https://en.wikipedia.org/wiki/Chowdhury_Gulam_Akbar$b$, 'en', NULL, $b$Author$b$, NULL, $b$Moulvibazar District$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$D. P. Chattopadhyaya$b$, DATE '1933-11-05', DATE '2022-02-13', $b$Professor Debi Prasad Chattopadhyaya (November 5, 1933 – February 13, 2022), was educated at the University of Calcutta and was Deputy Minister of Health of India and Union Minister of Commerce and Industry. He founded the Indian Council of Philosophical Research, New Delhi, and served as its Chairman. Till the end of his life, he served as the Chairman of the Centre for Studies in Civilizations, and General Editor of the Project of History of Indian Science, Philosophy and Culture, which produced a multi-volume cultural history of India.

Chattopadhyaya has authored many books on culture and philosophy. In 2009, he was awarded the Padma Vibhushan, India's second highest civilian award.

Awards: Padma Vibhushan in literature & education
Education: University of Calcutta

Source: Wikipedia — https://en.wikipedia.org/wiki/D._P._Chattopadhyaya$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/D.%20P.%20Chattopadhyaya%20Rajya%20Sabha%20photo.jpg?width=640$b$, $b$Philosopher, Writer, Politician$b$, NULL, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$D. P. Roy Choudhury$b$, DATE '1899-06-15', DATE '1975-10-15', $b$Devi Prasad Roy Choudhury  (15 June 1899 – 15 October 1975) was an Indian sculptor, painter and educator. He is well known for his monumental bronze sculptures, especially the Triumph of Labour and the Martyrs' Memorial, and is rated by many as one among the major artists of Indian modern art. He worked in a broad spectrum of mediums including watercolors, expressionist landscapes and commissioned portraits. Large scale sculptures were his particular strength and he made social realism the cornerstone of his art. In addition to painting and sculpting, he also wrestled, played the flute, engaged in hunting and wrote short stories in his spare time.

He served as the principal of Madras School of Art from 1929 to 1957 and became one of the first Indians to head a government educational institution at the time. The Government of India awarded him the third highest civilian honour of the Padma Bhushan, in 1958, for his contributions in the field of arts. He was elected as the Fellow of Lalit Kala Akademi in 1962.

Awards: Member of the Order of the British Empire
Education: Government College of Fine Arts, Chennai

Source: Wikipedia — https://en.wikipedia.org/wiki/D._P._Roy_Choudhury$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Deviprasad%20Roy%20Chowdhury.jpg?width=640$b$, $b$Painter, Sculptor, Writer$b$, $b$Rangpur$b$, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Dakshinaranjan Mitra Majumder$b$, DATE '1877-04-15', DATE '1957-03-30', $b$Dakshinaranjan Mitra Majumdar (15 April 1877 – 30 March 1957) was an Indian writer in Bengali of fairy tales and children's literature. He was born at Ulail in Dhaka district of Bengal province in British India (now Dhaka District of Bangladesh). His major contribution to Bengali literature was the collection and compilation of Bengali folk and fairy tales in four volumes – Thakurmar Jhuli (Grandmother's Bag of Tales), Thakurdadar Jhuli (Grandfather's Bag of Tales), Thandidir Thale (Maternal-Grandmother's Bag of Tales) and Dadamashayer Thale (Maternal-Grandfather's Bag of Tales).

Notable works: Kishorder Mon
Education: University of Calcutta

Source: Wikipedia — https://en.wikipedia.org/wiki/Dakshinaranjan_Mitra_Majumder$b$, 'en', NULL, $b$Writer, Novelist, Short story writer$b$, $b$Dhaka$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Daud Haider$b$, DATE '1952-02-21', DATE '2025-04-26', $b$Daud Haider (21 February 1952 – 26 April 2025) was a Bangladeshi poet who was forced into exile after writing a poem that "insulted" religions, including Islam. American Center, PEN International have described him as a "distinguished poet".

Source: Wikipedia — https://en.wikipedia.org/wiki/Daud_Haider$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/DaudHaider2007-Frankfurt.jpg?width=640$b$, $b$Writer, Poet$b$, NULL, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Daulat Qazi$b$, DATE '1600-01-01', DATE '1638-01-01', $b$Daulat Qazi (Bengali: দৌলত কাজী; c. 1600–1638) was a Bengali poet. He was born into the Qazi family of the village of Sultanpur in Raozan Upazila, Chittagong. Not getting any recognition at home, he left for Arakan, where he seems to have been received warmly.

