INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Daulatunnesa Khatun$b$, DATE '1918-01-01', DATE '1997-08-04', $b$Daulatunnesa Khatun (Bengali: দৌলতুননেসা খাতুন; 1918 - 4 August 1997) was a Bangladesh Nationalist Party politician and member of the Bangladesh Parliament in a women's reserved seat.

