INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Debaprasad Ghosh$b$, DATE '1894-03-15', DATE '1985-07-14', $b$Acharya Debaprasad Ghosh (15 March 1894 – 14 July 1985) was an Indian mathematician and politician. He began his career as a professor of mathematics at the Ripon College. He was involved in politics as the President of Bharatiya Jana Sangh, the political wing of the Rashtriya Swayamsevak Sangh (RSS), a far-right Hindutva paramilitary organisation. He served as the party president from 1956 to 1965, except for the period between 1960 and 1962.

Education: University of Calcutta, City College

Source: Wikipedia — https://en.wikipedia.org/wiki/Debaprasad_Ghosh$b$, 'en', NULL, $b$Politician, Mathematician, Writer$b$, $b$Barishal$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Debesh Roy$b$, DATE '1936-12-17', DATE '2020-05-14', $b$Debesh Roy (17 December 1936 – 14 May 2020) was an Indian Bengali language writer and scholar. He is best known for his Sahitya Akademi Award-winning novel Teesta Parer Brittanta (1990).

Awards: Sahitya Akademi Award

