INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Dewan Mohammad Azraf$b$, DATE '1906-10-25', DATE '1999-11-01', $b$Dewan Mohammad Azraf  (Bengali: দেওয়ান মোহাম্মদ আজরফ; 1908–1999) was a Bengali philosopher, teacher, author, politician, journalist and activist. In 1993, he was honoured as a National Professor in Bangladesh. He was also a supporter of the Bengali language movement. For his support of the movement, he was dismissed from the post of the principal of Sunamganj College in 1954, the same year he was promoted to the post. His support was particularly influential when he edited the Nao Belal in 1948. He was actively involved with Kaikobad Sahitya Majlish (1972–99).

Influenced by the thought of Muhammad Iqbal, he has been described as "a prolific writer" who "produced sixty monographs, over 1,000 articles in Bangla and English, 109 novels, poems, songs, and ninety short stories. His works range from literature, arts, music, and religion to philosophy."

Awards: Independence Award in Literature, Ekushey Padak, Honorary Fellow of Bangla Academy
Education: University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Dewan_Mohammad_Azraf$b$, 'en', NULL, $b$Philosopher, Academic, Writer$b$, NULL, NULL, 'day', 'day');
