INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Dinanath Sen$b$, DATE '1839-01-01', DATE '1898-01-01', $b$Dinanath Sen (1839/1840–1898) was a Bengali social reformer and journalist. He played an important role in the education and cultural spheres of 19th-century Dhaka. He served as the second editor of the first Bengali newspaper in Dhaka, Dhaka Prakash.

