INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Dwarkanath Ganguly$b$, DATE '1844-04-20', DATE '1898-06-27', $b$Dwarkanath Gangopadhyay (also known as Dwarkanath Ganguly, 20 April 1844–27 June 1898) was a Bengali Brahmo reformer. He made substantial contributions towards societal enlightenment and the emancipation of women. Ganguly dedicated his life to the latter cause, encouraging women to participate in politics and the social services. He was the husband of the first female Indian physician, Kadambini Ganguly.

Source: Wikipedia — https://en.wikipedia.org/wiki/Dwarkanath_Ganguly$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Dwarkanath%20Ganguly.jpg?width=640$b$, $b$Writer, Teacher, Editor, Social reformer$b$, $b$Munshiganj$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Dwijendralal Ray$b$, DATE '1863-07-19', DATE '1913-05-17', $b$Dwijendralal Ray (19 July 1863 – 17 May 1913), also known as D. L. Ray, was a Bengali poet, playwright, and musician. He was known for his Hindu mythological and nationalist historical plays and songs known as Dwijendrageeti or the Songs of Dwijendralal, which number over 500, create a separate subgenre of Bengali music.

Notable works: Ekghare
Education: Presidency University, Royal Agricultural University

Source: Wikipedia — https://en.wikipedia.org/wiki/Dwijendralal_Ray$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/%E0%A6%86%E0%A6%B7%E0%A6%BE%E0%A6%A2%E0%A6%BC%E0%A7%87%20-%20%E0%A6%A6%E0%A7%8D%E0%A6%AC%E0%A6%BF%E0%A6%9C%E0%A7%87%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8D%E0%A6%B0%E0%A6%B2%E0%A6%BE%E0%A6%B2%20%E0%A6%B0%E0%A6%BE%E0%A6%AF%E0%A6%BC%20%28%E0%A7%A7%E0%A7%AF%E0%A7%A7%E0%A7%AD%29%20%28page%203%20crop%29.jpg?width=640$b$, $b$Poet, Writer, Teacher, Civil servant, Composer, Playwright$b$, $b$Krishnanagar$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Emajuddin Ahamed$b$, DATE '1933-12-15', DATE '2020-07-17', $b$Emajuddin Ahamed (15 December 1933 – 17 July 2020) was a Bangladeshi political scientist, author and educationist. He served as the 21st vice-chancellor of the University of Dhaka during 1992–1996. He was awarded Ekushey Padak in 1992 by the Government of Bangladesh in the education category.

