INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Gauriprasanna Mazumder$b$, DATE '1925-12-05', DATE '1986-08-20', $b$Gauriprasanna Majumdar (5 December 1925 – 20 August 1986) was an Indian lyricist and writer known for his work in Indian cinema. He is most commonly associated with the black and white era of Bengali cinema, when he penned several enduring classics for films. Often considered as one of the greatest and most prominent lyricists of the golden era of Bengali cinema, he is a recipient of numerous accolades. He won the Bengal Film Journalists' Association Awards for best lyricist for Swaralipi (1962), Palatak (1964), Antony Firingee (1967), Bon Palashir Padabali (1974), Sanyasi Raja (1976) and Anurager Chhoan (1987, posthumously). He also won National Film Awards of Bangladesh for Sesh Porjonto (1969).

Source: Wikipedia — https://en.wikipedia.org/wiki/Gauriprasanna_Mazumder$b$, 'en', NULL, $b$Author, Lyricist, Songwriter$b$, $b$Pabna$b$, NULL, 'day', 'day');
