INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Gazi Mazharul Anwar$b$, DATE '1943-02-22', DATE '2022-09-04', $b$Gazi Mazharul Anwar (22 February 1943 – 4 September 2022) was a Bangladeshi film director, producer, lyricist, screenwriter and music director. He earned the Bangladesh National Film Award for Best Lyricist a record seven times for the films Tit for Tat (1992), Ajante (1996), Churiwala (2001), Lal Dariya (2002), Kokhono Megh Kokhono Brishti (2003), Meyeti Ekhon Kothay Jabe (2016) and Joiboti Konyar Mon (2021). He worked as a lyricist in the "Swadhin Bangla Betar Kendra". He was awarded Ekushey Padak in 2002 and Independence Day Award in 2021 by the government of Bangladesh. He has penned lyrics for 267 films.

Awards: Ekushey Padak
Education: Comilla Zilla School

Source: Wikipedia — https://en.wikipedia.org/wiki/Gazi_Mazharul_Anwar$b$, 'en', NULL, $b$Lyricist, Songwriter, Music director, Film director, Screenwriter$b$, $b$Cumilla District$b$, NULL, 'day', 'day');
