INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Gobinda Halder$b$, DATE '1930-08-01', DATE '2015-01-17', $b$Gobinda Halder (1930 – 17 January 2015) was a Bengali lyricist and poet. He wrote patriotic songs during the Bangladesh Liberation War of 1971 which include "Mora Ekti Phulke Bachabo Bole Juddho Kori", "Ek Sagor Rokter Binimoye Banglar Swadhinata Anlo Jara", "Purbo Digonte Surjo Uthechhe Rokto Lal", and "Padma Meghna Jamuna Tomar Amar Thikana".

