INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Hara Prasad Shastri$b$, DATE '1853-12-09', DATE '1931-11-17', $b$Hara Prasad Shastri (Bengali: হরপ্রসাদ শাস্ত্রী; 6 December 1853 – 17 November 1931), also known as Hara Prasad Bhattacharya, was an Indian academic, Sanskrit scholar, archivist, and historian of Bengali literature. He is most known for discovering the Charyapada, the earliest known examples of Bengali literature.

