INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Humayun Kabir$b$, DATE '1906-02-22', DATE '1969-08-18', $b$Humayun Kabir (1906–1969) was an Indian educationist and politician. He was also a poet, essayist and novelist in the Bengali language. He was also a renowned political thinker. He was educated at Exeter College, Oxford and graduated in 1931. Kabir had been heavily involved with the Oxford Union during his student days, having been elected secretary in 1930 and librarian in 1931. He made his farewell speech on the motion: 'This House condemns the Indian policy of His Majesty's Government'. Kabir had also been involved with the student newspapers, the Isis and the Cherwell, and the Oxford Majlis journal, Bharat.

Upon his return to India, Kabir taught at a number of universities. He also became involved in trade union politics and was elected to the Bengal Legislative Assembly in 1937. He took up a number of government posts after 1947, including Minister for Education.

Kabir published a book of poems in Oxford in 1932, and continued to write poetry, short stories and novels after his return to India. He also wrote essays and was a well-respected orator. He died in Kolkata in 1969.

Education: Exeter College, University of Calcutta, Presidency University

Source: Wikipedia — https://en.wikipedia.org/wiki/Humayun_Kabir_(Indian_National_Congress_politician)$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Humayun%20Kabeer%20at%20Perfect%20Chemical%20Industries%20%28cropped%29.jpg?width=640$b$, $b$Politician, University teacher, Writer, Civil servant, Pedagogue, Philosopher$b$, $b$Faridpur District$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Humayun Kabir$b$, DATE '1948-12-25', DATE '1972-06-06', $b$Humayun Kabir (25 December 1948 – 6 June 1972) was a progressive poet of the Bengali language in the 20th century. He was involved in leftist politics and was a teacher in the Department of Bengali at the University of Dhaka. In 1972, he was killed due to internal conflicts within the Proletarian Party of East Bengal.

Source: Wikipedia — https://en.wikipedia.org/wiki/Humayun_Kabir_(poet)$b$, 'en', NULL, $b$Poet$b$, NULL, NULL, 'day', 'day');
