INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Husne Ara Kamal$b$, DATE '1935-01-01', DATE '2009-04-16', $b$Husne Ara Kamal (Bengali: হোসনে আরা কামাল; 20 December 1934 – 16 April 2009) was a Bangladeshi academic, philanthropist, and social worker who made significant contributions to social welfare and women's empowerment in Bangladesh throughout her career. She worked as a lecturer and later became the director and a professor at the Institute of Social Welfare and Research in Dhaka, Bangladesh. Kamal was also an accomplished author and published several books on women and gender issues, as well as books for children.

