INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Ihsanul Karim$b$, DATE '1951-01-05', DATE '2024-03-10', $b$Ihsanul Karim (Bengali: ইহসানুল করিম; 5 January 1951 – 10 March 2024) was a Bangladeshi journalist. He was the press secretary to the Prime Minister of Bangladesh. Prior to his appointment at the Prime Minister's Office, Karim worked as the Press Secretary to the President. He also served as the Managing Director and Chief Editor of Bangladesh Sangbad Sangstha (BSS), Bangladesh's state-run national news agency.

