INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Ismail Hossain Siraji$b$, DATE '1880-01-01', DATE '1931-01-01', $b$Syed Ismail Hossain Siraji (Bengali: সৈয়দ ইসমাইল হোসেন সিরাজী; 1880–1931) was a Bengali royal as well as an author and poet from Sirajganj in present-day Bangladesh. He is considered to be one of the key authors of period of the Bengali Muslim reawakening; encouraging education and glorifying the Islamic heritage. He also contributed greatly to introducing the Khilafat Movement in Bengal, and provided medical supplies to the Ottoman Empire during the Balkan Wars. Anal-Prabaha, his first poetry book, was banned by the government and he was subsequently imprisoned as the first South Asian poet to allegedly call for independence against the British Raj. The government issued Section 144 against him 82 times in his lifetime.

Notable works: Spainiyo Musalman Sabhyata, Anal-prabaha

Source: Wikipedia — https://en.wikipedia.org/wiki/Ismail_Hossain_Siraji$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Ismail%20hossian%20siraji.jpg?width=640$b$, $b$Poet, Writer$b$, $b$Sirajganj District$b$, NULL, 'year', 'year');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Jadunath Majumdar$b$, DATE '1859-10-23', DATE '1932-10-24', $b$Jadunath Majumdar, Rai Bahadur (23 October 1859 – 24 October 1932) was a Bengali journalist and writer. He was the editor of the Tribune in Lahore, United India, and the Hindu Patrika of Jessore. Majumdar was also the founder of the journal, Sanmilani, in Jessore. He become a member of the first Legislative Assembly and the Bengal Legislative Council.

He was born at Lohagara, Narail.

Majumdar died at the age of 74 on 24 October 1932 at Rajbati Magura then a subdivision of Jessore district of undivided Bengal (now in Bangladesh).

Notable works: Upabas
Education: University of Calcutta

Source: Wikipedia — https://en.wikipedia.org/wiki/Jadunath_Majumdar$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Jadunath%20Majumdar.jpg?width=640$b$, $b$Writer, Editor$b$, $b$Narail$b$, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Jadunath Sarkar$b$, DATE '1870-12-10', DATE '1958-05-19', $b$Sir Jadunath Sarkar,  (10 December 1870 – 19 May 1958) was a prominent Indian historian and a specialist on the Mughal dynasty.

Sarkar was educated in English literature and worked as a teacher for some time but later shifted his focus to history research writing. He had vast knowledge of the Persian language, and he wrote all his books in English. He was vice-chancellor (VC) of the University of Calcutta from 1926 to 1928 and a member of the Bengal Legislative Council between 1929 and 1932. In 1929 the British knighted him.

Awards: Companion of the Order of the Indian Empire, Knight Bachelor
Education: University of Calcutta, Presidency University, Rajshahi College

Source: Wikipedia — https://en.wikipedia.org/wiki/Jadunath_Sarkar$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Jadunath%20Sircar.jpg?width=640$b$, $b$Writer, Historian, University teacher$b$, $b$Natore District$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Jagadish Gupta$b$, DATE '1886-07-01', DATE '1957-04-15', $b$Jagadish Gupta (5 July 1886 – 15 April 1957) was an Indian poet, novelist and short story writer. Known for his realistic view of life, strange character portrayal and unique narrative style, he was one of the major exponents of modern Bengali literature.

Born as Jagadish Chandra Sengupta in Kushtia, Bengal Presidency, he studied in Calcutta and later took up work as a 'job-typist' at the Judge's Court in Seuri. He also worked at Executive Engineer's office in Sambalpur, Orissa, at Patna High Court and at Bolpur Chawki Adalat as a typist. After retirement from his job, he settled in Calcutta. The Government of India granted him a 'Distinguished Man of Letters Allowance' in 1954.

Gupta's stories had been published in periodicals like Bharati, Bijoli, Uttara, Kali-Kalam and Kallol. His first novel Asadhu Siddhartha was published in 1928. Some of his other notable works include Binodini, Udaylekha, Meghabrito Ashani, Dulaler Dola, Nishedher Patabhumikay, Loghu Guru etc.

Education: University of Calcutta, Surendranath College

Source: Wikipedia — https://en.wikipedia.org/wiki/Jagadish_Gupta$b$, 'en', NULL, $b$Poet, Novelist, Writer$b$, $b$Kushtia District$b$, $b$Kolkata$b$, 'month', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Jaladhar Sen$b$, DATE '1860-03-13', DATE '1939-03-15', $b$Rai Bahadur Jaladhar Sen (13 March 1860 – 15 March 1939) was a Bengali writer, poet, editor, philanthropist, traveler, social worker, educationist, and littérateur. He was awarded the title Ray Bahadur by the British government.

Source: Wikipedia — https://en.wikipedia.org/wiki/Jaladhar_Sen$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Portrait%20of%20Jaladhar%20Sen.jpg?width=640$b$, $b$Writer, Editor, Novelist, Biographer, Short story writer$b$, $b$Kumarkhali$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Jalaluddin Jalal$b$, DATE '1923-10-05', DATE '1977-01-01', $b$Jalaluddin Jalal (Persian: جلال الدین جلال; 1923–1977), was an Afghan writer, poet and painter.

Source: Wikipedia — https://en.wikipedia.org/wiki/Jalaluddin_Jalal$b$, 'en', NULL, $b$Poet, Politician$b$, NULL, NULL, 'day', 'year');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Jamini Bhushan Ray$b$, DATE '1879-07-01', DATE '1926-08-11', $b$Jamini Bhushan Ray (Bengali: যামিনী ভূষণ রায়; 1 July 1879 (17 Asharh 1286 BS) – 11 August 1926 (26 Srabon 1333 BS)) was an Indian Ayurvedic physician, Sanskrit scholar, educator, and philanthropist. He founded the Ashtanga Ayurveda College and Hospital in Calcutta in 1916 and established the Vaidyaraj Pharmacy, both of which formed part of his efforts to modernise Ayurvedic education and pharmaceutical practice during the late colonial period. Contemporary scholarship identifies him as an important figure in the revival of Ayurveda in Bengal through the development of educational institutions, pharmaceutical enterprises and professional organisations.

Trained in both Sanskrit scholarship and Western medicine, Ray advocated the systematic study of Ayurveda and promoted formal education, clinical training and scholarly publication alongside its classical traditions.

Education: University of Calcutta, The Sanskrit College and University, South Suburban School (Main), Medical College and Hospital, Kolkata

Source: Wikipedia — https://en.wikipedia.org/wiki/Jamini_Bhushan_Ray$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Portrait%20of%20Jamini%20Bhushan%20Ray.png?width=640$b$, $b$Ayurveda practitioner, Medical faculty, Writer, Philanthropist$b$, $b$Khulna$b$, $b$Kolkata$b$, 'day', 'day');
