INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Kazi Abu Zafar Siddique$b$, DATE '1904-09-13', DATE '2012-10-15', $b$Kazi Abu Zafar Mohammed Hasan Siddiqui (1940 – 15 October 2012) was a recital artist and cultural activist of Bangladesh. He was the director general of Bangladesh Television. According to Kazi Nazrul Islam's eldest son, the first winner of the Kazi Sabyasachi Award was the personification of Cultural Personality, launched by the Ministry of Culture of the Government of Bangladesh.

