INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Kazi Abul Kasem$b$, DATE '1913-05-07', DATE '2004-07-19', $b$Kazi Abul Kasem, (; 7 May 1913 – 19 July 2004) pseudonym Dopiaza, was a Bangladeshi polymath, pathfinder creative professional who is known as the very first Muslim cartoonist in the Indian subcontinent. Painting and drawing cartoons for many different renowned magazines from 1937 to 1980, Kasem have played different roles in his region from using arts to influence political movement to paint masterpieces for the national museum.

Kasem was awarded for painting best cover art for children's publication by Bangla Academy, he was awarded for promoting child literature twice in a row by National Book Council of Bangladesh. Many of his assorted line drawings and illustrations were used in school's national textbook.

Awards: Bangla Academy Literary Award

Source: Wikipedia — https://en.wikipedia.org/wiki/Kazi_Abul_Kasem$b$, 'en', NULL, $b$Lyricist, Songwriter, Painter, Writer$b$, $b$Jhenaidah District$b$, $b$Dhaka$b$, 'day', 'day');
