INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Khwaja Ahsanullah$b$, DATE '1846-08-22', DATE '1901-12-16', $b$Nawab Bahadur Sir Khwaja Ahsanullah KCIE (22 August 1846 – 16 December 1901) was the third Nawab of Dhaka. He was notable for his philanthropic works in Bengal, notably his donations to the present Bangladesh University of Engineering and Technology and for introducing electricity in his native city of Dhaka. He also authored books in Persian and Urdu under the pen name of Shaheen. The palace Ahsan Manzil is named after him by his father, Khwaja Abdul Ghani.

Awards: Knight Commander of the Order of the Indian Empire

Source: Wikipedia — https://en.wikipedia.org/wiki/Khwaja_Ahsanullah$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Khwaja%20Ahsanullah.jpg?width=640$b$, $b$Writer$b$, $b$Dhaka$b$, NULL, 'day', 'day');
