INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Madhusūdana Sarasvatī$b$, DATE '1540-01-01', DATE '1647-01-01', $b$Madhusūdana Sarasvatī (c.1490–1580) was an Indian philosopher in the Advaita Vedānta tradition and devotee of Krishna. He was the disciple of Viśveśvara Sarasvatī and Mādhava Sarasvatī.

Madhusūdana composed Advaitasiddhi, a line-by-line refutation of Nyayamṛta. In response to Advaitasiddhi, the Dvaita scholars, Vyasa Ramacharya, and Ananda Bhattaraka, wrote Nyayamṛta Tarangini and Nyayamṛta Kantakoddhara and challenged Madhusūdana Sarasvatī.

