INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Mahasweta Devi$b$, DATE '1926-01-14', DATE '2016-07-28', $b$Mahasweta Devi (Bengali pronunciation: [mɔhaʃːeta debi]; 14 January 1926 – 28 July 2016) was an Indian Bengali language writer and activist. Her notable literary works include Hajar Churashir Maa, Rudali, and Aranyer Adhikar. She was a leftist who worked for the rights and empowerment of the tribal people (Lodha and Shabar) of West Bengal, Bihar, Madhya Pradesh and Chhattisgarh states of India. She was honoured with various literary awards such as the Sahitya Akademi Award (in Bengali), Jnanpith Award and Ramon Magsaysay Award along with India's civilian awards Padma Shri and Padma Vibhushan.

Notable works: Hajar Churashir Maa
Awards: Sahitya Akademi Award in Bengali, Ramon Magsaysay Award, Banga Bibhushan, Jnanpith Award, Officer of Arts and Letters, Padma Shri in social work, Padma Vibhushan in literature & education, SAARC Literary Award
Education: University of Calcutta, Visva-Bharati University

