INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Manik Bandopadhyay$b$, DATE '1908-05-19', DATE '1956-12-03', $b$Manik Bandyopadhyay [alias Banerjee] (; 19 May 1908 – 3 December 1956) is an Indian author regarded as one of the major figures of 20th century Bengali literature. His birth name is Prabodhkumar Bandyopadhyay. During a lifespan of 48 years and 28 years of literary career, battling with epilepsy from the age of around 28 and financial strains all along, he produced some masterpieces of novels and short stories, besides some poems, essays etc. One of the early neo-realist film shot in Pakistan, The Day Shall Dawn is based on his story.

