INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Mihir Sengupta$b$, DATE '1946-01-01', DATE '2022-01-17', $b$Mihir Sengupta (1946 – 17 January 2022) was an Indian writer of Bengali literature.

He was best known for his 2005 autobiography Bishaad Brikkho ('Tree of Sorrow'). It describes the atrocities of post-partition East Pakistan as seen by the author, who was uprooted from his native Barisal in present-day Bangladesh and ended up in Calcutta as a refugee. Bishaad Brikkho is regarded as an important literary document of the atrocities of post-partition West Pakistan and won the Ananda Puroshkar literary prize. Sengupta died in Kolkata of blood cancer on 17 January 2022, at the age of 75.

Awards: Ananda Puraskar

Source: Wikipedia — https://en.wikipedia.org/wiki/Mihir_Sengupta$b$, 'en', NULL, $b$Writer, Autobiographer$b$, NULL, $b$Kolkata$b$, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Mir Mosharraf Hossain$b$, DATE '1847-11-13', DATE '1912-01-01', $b$Mir Syed Mosharraf Hossain (Bengali: মীর মুশাররফ হুসাইন; 13 November 1847– 19 December 1911) was a Bengali writer, novelist, playwright, and essayist. He is considered to be the first major writer to emerge from the Shia society of Bengal, and one of the finest prose writers in the Bengali language. His magnum opus Bishad Shindhu (Ocean of Sorrow) is a popular classic among the Bengali readership.

Source: Wikipedia — https://en.wikipedia.org/wiki/Mir_Mosharraf_Hossain$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Mir%20mosharraf%20hossain.jpg?width=640$b$, $b$Writer, Playwright, Essayist$b$, $b$Pangsha Upazila$b$, NULL, 'day', 'year');
