INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Mohammad Hannan$b$, DATE '1949-12-14', DATE '2014-01-21', $b$Mohammad Hannan (14 December 1949 – 21 January 2014) was a Bangladeshi film director and producer. He was known for directing several notable commercial films in Dhallywood. He entered the film industry as an assistant to Baby Islam. His first film was Rai Binodini (1985). His notable films include Bikkhob (1994), Praner Cheye Priyo (1997), Bidroho Charidike (2000), and Sahoshi Manush Chai (2003). He won the Bachsas Award for Best Dialogue Writer. His last film, Shikhandi Kotha (2013), won the Meril-Prothom Alo Award in the Best Film Director category.

