INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Motiur Rahman Rentu$b$, DATE '1954-01-01', DATE '2007-01-01', $b$Motiur Rahman Rentu was a Bangladeshi politician and a writer. He has been widely popularity for his book Amar Fashi Chai, which vehemently criticized former prime minister of Bangladesh Sheikh Hasina, during whose rule the book was banned.

