INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Muhammad Faizullah$b$, DATE '1892-01-01', DATE '1976-01-01', $b$Mufti Faizullah (Bengali: মুফতি ফয়জুল্লাহ), was a Bangladeshi Deobandi Islamic scholar, mufti, poet, educator and a reformer. He was among early students to study at the Darul Uloom Hathazari. He was an alumnus of Darul Uloom Deoband and later served as the Chief Mufti of the Darul Uloom Hathazari. He established Mekhal Madrasa following in the style of Ashab-e Suffah. He authored over 100 books in Arabic, Persian and Urdu.

