INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Muhammad Kamaruzzaman$b$, DATE '1952-07-04', DATE '2015-04-11', $b$Muhammad Kamaruzzaman (4 July 1952 – 11 April 2015) was a Bangladeshi politician and journalist who served as the senior assistant secretary general of Bangladesh Jamaat-e-Islami and was convicted of war crimes during the 1971 independence war of Bangladesh. He was executed by hanging at Dhaka Central Jail at 22:01 on 11 April 2015.

Besides his political career, Kamaruzzaman also was editor of the Weekly Sonar Bangla. On 9 May 2013, the International Crimes Tribunal sentenced him to death after it found Kamaruzzaman guilty of crimes against humanity including genocide, murder, rape, looting, arson, and deportation of people during the Bangladesh War of Independence. Kamaruzzaman denied all charges, stating they were politically motivated. The trial itself was criticized by international observers and opposition figures and was mired in controversies.

Education: University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Muhammad_Kamaruzzaman$b$, 'en', NULL, $b$Politician, Journalist$b$, NULL, $b$Dhaka$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Muhammad Mohar Ali$b$, DATE '1932-01-01', DATE '2007-04-11', $b$Muhammad Mohar Ali (Bengali: মোহাম্মদ মোহার আলী); 1929–2007) was a British Bangladeshi lecturer, historian, barrister and Islamic scholar. He is the only Bengali to have received the King Faisal International Prize.

Awards: King Faisal Prize in Islamic Studies
Education: SOAS, University of London, University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Muhammad_Mohar_Ali$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Muhammad%20Mohar%20Ali.jpg?width=640$b$, $b$Historian, Writer$b$, $b$Khulna$b$, NULL, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Muhammad Mustafizur Rahman$b$, DATE '1941-01-01', DATE '2014-01-14', $b$Muhammad Mustafizur Rahman (January 1, 1941 – January 14, 2014) was a Bangladeshi Islamic scholar, academic and Quran translator. He served as the seventh vice chancellor of Islamic University, Bangladesh from December 10, 2001, to April 2, 2004. He also served as a professor at the University of Dhaka. The first Bangladeshi scholar to translate the Qur'an into English, Rahman wrote many books and scholarly articles on Islam.

Education: University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Muhammad_Mustafizur_Rahman$b$, 'en', NULL, $b$Writer, University teacher, Translator$b$, $b$Mathbaria Upazila$b$, NULL, 'day', 'day');
