INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Muhammad Shahidullah$b$, DATE '1885-07-10', DATE '1969-07-13', $b$Muhammad Shahidullah (Bengali: মুহম্মদ শহীদুল্লাহ, pronounced [muɦɔmːɔd̪ ʃoɦid̪ulːaʱ]; 10 July 1885 – 13 July 1969) was a Bengali linguist, philologist, educationist, and writer. He played a vital role in Bangladesh's Language movement of 1952. He is primarily credited for being the one to justify why Bengali should be the state language of Pakistan over Urdu.

In 2004, he was ranked number 16 in the BBC's opinion poll Greatest Bengali of all time. According to linguist Pabitra Sarkar, Shahidullah is one of the best scholars of linguistics that South Asia ever produced. A residential hall at Dhaka University has been named after him since 1969.

Awards: Pride of Performance, Independence Award in Education, Honorary Fellow of Bangla Academy
Education: University of Paris, University of Calcutta, Presidency University, City College

Source: Wikipedia — https://en.wikipedia.org/wiki/Muhammad_Shahidullah$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Mohammod%20Sohidullah.jpg?width=640$b$, $b$Linguist, Lawyer, Researcher, Teacher, Writer$b$, $b$Piyara$b$, $b$Dhaka$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Muhammad Wajed Ali$b$, DATE '1896-01-01', DATE '1954-11-08', $b$Muhammad Wajed Ali (September 12, 1896 – November 8, 1954) was an East Pakistani (current Bangladesh) Writer and Journalist.

