INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Mujibur Rahman Dulu$b$, DATE '1955-01-01', DATE '2025-05-31', $b$Mujibur Rahman Dulu was a Bangladeshi film editor. He won Bangladesh National Film Award for Best Editing eight times for the films Bhat De (1984), Teen Kannya (1985), Satya Mithya (1989), Pita Mata Santan (1991), Banglar Bodhu (1993), Meghla Akash (2001), Itihas (2002) and Abujh Bou (2010).

Source: Wikipedia — https://en.wikipedia.org/wiki/Mujibur_Rahman_Dulu$b$, 'en', NULL, $b$Film editor, Screenwriter$b$, NULL, NULL, 'year', 'day');
