INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Mukul Chowdhury$b$, DATE '1946-01-01', DATE '2002-01-01', $b$Mukul Chowdhury (Bangla:মুকুল চৌধুরী) was a Bangladeshi lyricist and musical artist. He wrote many songs for radio, television and more than hundreds of films including 'O Madhobi Go Theko Mor Antore,' 'Tumi Accho Sobi Acche,' 'Ek Chor Jay Chole' and 'Ore Nil Doriya Amay De Re De Chhariya.'

