INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Munshi Mohammad Meherullah$b$, DATE '1861-01-01', DATE '1907-05-07', $b$Munshi Mohammad Meherullah (1861 – 7 May 1907) was a Bengali Islamic scholar, poet, and social reformer. He is the first person in history with the title Bangabandhu, and is best known for his oratory and writing on Islam and comparative religion. His efforts have been compared to Raja Ram Mohan Roy's defense of Hinduism against anti-Hindu views expounded by Christian missionaries in India.

Source: Wikipedia — https://en.wikipedia.org/wiki/Munshi_Mohammad_Meherullah$b$, 'en', NULL, $b$Writer$b$, $b$Kaliganj Upazila$b$, NULL, 'year', 'day');
