INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Mushtaq Ahmed$b$, DATE '1967-12-05', DATE '2021-02-25', $b$Mushtaq Ahmed (Bengali: মুশতাক আহমেদ; 5 December 1967 – 25 February 2021), popularly known as Kumir Bhai, was a Bangladeshi dissident, writer, and entrepreneur. His pen name was Michael Kumir Thakur. He founded the first ever commercial Crocodile breeding farm in Bangladesh. His book Kumir Chashir Diary was published in 2018. He was working on another book. He was accused with 10 others of sharing cartoons in social media posts criticizing the Bangladeshi government's corrupt and mismanaged response to COVID-19 pandemic and was detained in pre-trial for almost a year. On 25 February 2021 he died in jail, after being denied bail 6 times.

He was the first "martyr" of the notorious 2018 Digital Security Act.

Education: University of Chittagong

Source: Wikipedia — https://en.wikipedia.org/wiki/Mushtaq_Ahmed_(writer)$b$, 'en', NULL, $b$Journalist$b$, NULL, $b$Gazipur District$b$, 'day', 'day');
