INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Nabendu Ghosh$b$, DATE '1917-03-27', DATE '2007-12-15', $b$Nabendu Ghosh (27 March 1917 – 15 December 2007) was an Indian author in Bengali literature, and screenwriter. He has written screenplays of classic Bollywood movies like, Sujata, Bandini, Devdas, Majhli Didi, Abhimaan and Teesri Kasam. He has written stories for movies like Baap Beti, Shatranj, Raja Jani. He has also acted briefly in Do Bigha Zameen, Teesri Kasam and Lukochuri. Later in his career, he directed four movies as well.

Awards: Filmfare Awards

Source: Wikipedia — https://en.wikipedia.org/wiki/Nabendu_Ghosh$b$, 'en', NULL, $b$Film director, Autobiographer, Writer, Screenwriter$b$, $b$Dhaka$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Nabinchandra Sen$b$, DATE '1847-02-10', DATE '1909-01-23', $b$Nabinchandra Sen (Bengali: নবীনচন্দ্র সেন; 10 February 1847 – 23 January 1909) was a Bengali poet and writer, often considered one of the greatest poets prior to the arrival of Rabindranath Tagore. He commented on the Battle of Plassey and the arrival of British rule in India as "a night of Eternal Gloom".

Education: Presidency University, Scottish Church College, Chattogram Collegiate School

Source: Wikipedia — https://en.wikipedia.org/wiki/Nabinchandra_Sen$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Nabin%20Chandra%20Sen.jpg?width=640$b$, $b$Poet, Translator, Autobiographer, Writer$b$, $b$Chittagong$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Najma Sadeque$b$, DATE '1945-01-01', DATE '2015-01-08', $b$Najma Sadeque (1943 – 8 January 2015) from Pakistan was a leading woman journalist, author, human rights activist, particularly of women's rights, an artist, environmentalist,  and painter. She also did research on socioeconomic issues and authored many books and wrote articles. She co-founded Shirkat Gah in 1975, a women's NGO to highlight human rights violations against women. She also co-founded the Women’s Action Forum (WAF), Pakistan.

Source: Wikipedia — https://en.wikipedia.org/wiki/Najma_Sadeque$b$, 'en', NULL, $b$Painter, Journalist, Human rights defender$b$, $b$Bengal$b$, $b$Karachi$b$, 'year', 'day');
