INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Narayan Gangopadhyay$b$, DATE '1918-02-04', DATE '1970-11-08', $b$Narayan Gangopadhyay (born Taraknath Gangopadhyay; 4 February 1918–8 November 1970) was an Indian writer and academic, noted for his contributions to modern Bengali literature. He wrote novels, short stories, essays, plays, and children's literature. He is best known for creating the fictional character Tenida, a popular figure in Bengali juvenile fiction. He wrote under the pen name "Narayan."

He was awarded the literary awards Basumati Literary Prize (1968).

Education: University of Calcutta, Brojomohun College, Dinajpur Zilla School

