INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Nassakh$b$, DATE '1833-01-01', DATE '1889-06-14', $b$Khan Bahadur Abu Muḥammad Abdul Ghafur (11 February 1834 – 14 June 1889), better known by his pen name Nassakh (Urdu: نساخ), was a British Indian officer, writer, literary critic and collector. He is best known for his magnum opus Sukhan-e-Shuara (Urdu: سخن شعرا Speech of Poets) which was a biography of prominent Urdu and Persian poets. He organised mushaira in places where he worked; inspiring young Urdu poets in Bengal.

