INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Nazrul Islam Babu$b$, DATE '1949-07-17', DATE '1990-09-14', $b$Nazrul Islam Babu (17 July 1949 – 14 September 1990) was a Bangladeshi lyricist and freedom fighter . His notable songs include "Sob Kota Janala Khule Dao Na", "O Amar Aat Koti Phul" and "Ekti Bangladesh Tumi Jagroto Janotar". He won Bangladesh National Film Award for Best Lyrics for the film Padma Meghna Jamuna (1991).

