Source: Wikipedia — https://en.wikipedia.org/wiki/Nazrul_Islam_Babu_(lyricist)$b$, 'en', NULL, $b$Lyricist$b$, $b$Jamalpur District$b$, $b$Dhaka$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Nesaruddin Ahmad$b$, DATE '1873-01-01', DATE '1952-01-31', $b$Nesaruddin Ahmad (Bengali: নেছারউদ্দীন আহমদ; 1873 – 31 January 1952) was a Bengali Islamic scholar, spiritual reformer, educationist and writer. He was the main disciple of Furfura Sharif's Mohammad Abu Bakr Siddique in eastern Bengal. Ahmad was the inaugural Pir of Sarsina (Bengali: শর্ষিণার পীর), having founded the Sarsina Darbar Sharif and Darussunnat Kamil Madrasa in 1915, one of the largest Islamic institutions in South Bengal and the first major alia madrasah after Calcutta. Ahmad was among the leading Islamic leaders in colonial Barisal, and his influence extended across Bengal. The Nesarabad Upazila of Bangladesh has been named after him.

Notable works: Sarsina Darbar Sharif, Sarsina Darussunnat Kamil Madrasah
Education: Aliah University, Hooghly Madrasah

Source: Wikipedia — https://en.wikipedia.org/wiki/Nesaruddin_Ahmad$b$, 'en', NULL, $b$Writer, Murshid, Islamic cleric, Ulema, Activist$b$, $b$Swarupkat Upazila$b$, NULL, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Nihar Ranjan Gupta$b$, DATE '1911-06-06', DATE '1986-02-20', $b$Nihar Ranjan Gupta (Bengali: নীহাররঞ্জন গুপ্ত, pen name: Banbhatta (বানভট্ট); 6 June 1911 – 20 February 1986) was an Indian dermatologist and a popular Bengali novelist. He is the creator of the fictional detective character Kiriti Roy. Some of his writings were made into films of Bengal and Bollywood.

