INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Nirad C. Chaudhuri$b$, DATE '1897-11-23', DATE '1999-08-01', $b$Nirad Chandra Chaudhuri CBE (23 November 1897 –  1 August 1999) was an Indian writer.

In 1990, Oxford University awarded Chaudhuri, by then a long-time resident of the city of Oxford, an Honorary Degree in Letters. In 1992, he was made an honorary Commander of the Order of the British Empire (CBE).

