INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Omar Ali$b$, DATE '1939-10-20', DATE '2015-12-03', $b$Omar Ali (20 October 1939 – 3 December 2015) was a Bangladeshi poet. He was awarded Ekushey Padak by the Government of Bangladesh in 2017.

