INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Osman Hadi$b$, DATE '1993-01-01', DATE '2025-12-18', $b$Sharif Osman Bin Hadi (born Osman Goni; 1 January 1993 – 18 December 2025) was a Bangladeshi political and cultural activist, writer and a teacher. He was the co-founder and spokesperson of Inqilab Moncho. After the July Uprising, he became a prominent figure in youth-led movements, noted for his opposition to what he termed "Indian hegemony in Bangladesh", his advocacy regarding the July martyrs, and his participation in the Awami League ban protests.

On 12 December 2025, Hadi was shot in the Paltan area of Dhaka. He was airlifted to the Singapore General Hospital on 15 December, where he died three days later. His assassination sent shockwaves throughout Bangladesh, leading to widespread national mourning and cementing his legacy as a martyr among the youth and activist communities. The intense public grief over his murder also sparked significant nationwide unrest, underscoring his profound impact and popularity across the country.

Education: University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Osman_Hadi$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/%E0%A6%93%E0%A6%B8%E0%A6%AE%E0%A6%BE%E0%A6%A8%20%E0%A6%B9%E0%A6%BE%E0%A6%A6%E0%A6%BF.jpg?width=640$b$, $b$Politician, University teacher, Writer$b$, $b$Nalchity Upazila$b$, $b$Singapore General Hospital$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$P. C. Sorcar$b$, DATE '1913-02-23', DATE '1971-01-06', $b$Protul Chandra Sorcar (23 February 1913 – 6 January 1971) was an Indian magician. He performed internationally throughout the 1950s and 1960s. He has been called the "Father of Modern Indian Magic."

He is also known as P.C. Sorcar Senior, since his son, P.C. Sorcar Jr. also performs under that name.

Awards: Padma Shri in arts

Source: Wikipedia — https://en.wikipedia.org/wiki/P._C._Sorcar$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Stamp%20of%20India%20-%202010%20-%20Colnect%20259552%20-%20P%20C%20Sorcar.jpeg?width=640$b$, $b$Magician, Writer$b$, $b$Tangail District$b$, $b$Asahikawa$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Padmanath Bhattacharya$b$, DATE '1868-01-01', DATE '1938-01-01', $b$Padmanath Bhattacharya (Bengali: পদ্মনাথ ভট্টাচার্য; 1868-1938) was an Indian historian. His works generally centred on the ancient Kamrup region. The Padmanath Vidyabinod Memorial Awards are named after him.

Education: Dhaka College

Source: Wikipedia — https://en.wikipedia.org/wiki/Padmanath_Bhattacharya$b$, 'en', NULL, $b$Historian, Writer, Professor, Essayist, Travel writer$b$, $b$Sylhet$b$, NULL, 'month', 'year');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Paritosh Sen$b$, DATE '1918-10-18', DATE '2008-10-22', $b$Paritosh Sen (Bengali: পরিতোষ সেন) (26 September 1918 – 22 October 2008) was a leading Indian artist. He was born in Dhaka (then known as Dacca), the present-day capital of Bangladesh. He was a founder member of the Calcutta Group, an art movement established in 1942 that did much to introduce modernism into Indian art.

Sen pursued his artistic training at the Academie Andre Lhote, the Academie la Grande Chaumiere, the Ecole des Beaux Arts, and the Ecole des Louvre in Paris. Upon his return to India, he taught first in Bihar and then at Jadavpur University.

He also taught art at The Daly College at Indore during the late 1940s.

In 1969 he was the recipient of the French Fellowship for Designing and Typeface and in 1970 he was awarded a Rockefeller Fellowship. Sen has exhibited widely both in India and abroad, including the Calcutta Group exhibition (1944), London (1962), São Paulo Biennale (1965), New Delhi Triennale (1968, 1971, 1975), Sweden (1984), and the Havana Biennale (1986).

In 1959/60, Sen published Zindabahar, a book of autobiographical sketches in which he memorialized the Dacca city of his childhood.

He died in Kolkata.

Education: Académie de la Grande Chaumière

Source: Wikipedia — https://en.wikipedia.org/wiki/Paritosh_Sen$b$, 'en', NULL, $b$Painter, Writer$b$, $b$Dhaka$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Prabir Ghosh$b$, DATE '1945-03-01', DATE '2023-04-07', $b$Prabir Ghosh (1 March 1945 – 7 April 2023) was the founder and president of Bharatiya Bigyan O Yuktibadi Samiti, a science and rationalists' association based in Kolkata, India. He was the author of a number of books in Bengali disputing supernatural claims and was well known for his book series titled Aloukik Noy, Loukik.

Notable works: Aloukik Noy, Loukik, Jaubaner Bajranirghosh
Education: Dum Dum Motijheel College

Source: Wikipedia — https://en.wikipedia.org/wiki/Prabir_Ghosh$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Prabir%20Ghosh%2001.jpg?width=640$b$, $b$Writer, Civil rights advocate, Author$b$, $b$Umedpur$b$, $b$South Dum Dum$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Prabodh Chandra Bagchi$b$, DATE '1898-11-18', DATE '1956-01-19', $b$Prabodh Chandra Bagchi (Bengali: প্রবোধচন্দ্র-বাগচী) (18 November 1898 – 19 January 1956) was one of the most notable Sino-Indologists of the 20th century. He was the third Vice-Chancellor of Visva-Bharati University.

Education: University of Paris, Krishnagar Government College

Source: Wikipedia — https://en.wikipedia.org/wiki/Prabodh_Chandra_Bagchi$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Dr%20PC%20Bagchi%20at%20work.jpg?width=640$b$, $b$Historian, Linguist, Writer, Editor, University teacher, Sinologist$b$, $b$Jashore District$b$, $b$Santiniketan$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Prafulla Chandra Ray$b$, DATE '1861-08-02', DATE '1944-06-16', $b$Sir Prafulla Chandra Ray CIE FNI FRASB FIAS FCS (also spelled Prafulla Chandra Roy; Bengali: প্রফুল্ল চন্দ্র রায় Prôphullô Côndrô Rāẏ; 2 August 1861 – 16 June 1944) was an Indian chemist, educationist, historian, industrialist and philanthropist from Bengal. He established the first modern Indian research school in chemistry (post classical age) and is regarded as the father of Indian chemistry.

The Royal Society of Chemistry honoured his life and work with the first ever chemical landmark plaque outside Europe. He was the founder of Bengal Chemicals & Pharmaceuticals, India's first pharmaceutical company. He is the author of  A History of Hindu Chemistry from the Earliest Times to the Middle of the Sixteenth Century (1902).

Notable works: A History of Hindu Chemistry Vol 1
Awards: Companion of the Order of the Indian Empire, Knight Commander of the Order of the Indian Empire, Knight Bachelor
Education: University of Edinburgh, Presidency University, Vidyasagar College, Hare School

Source: Wikipedia — https://en.wikipedia.org/wiki/Prafulla_Chandra_Ray$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/%E0%A6%86%E0%A6%A4%E0%A7%8D%E0%A6%AE%E0%A6%9A%E0%A6%B0%E0%A6%BF%E0%A6%A4%20%28%E0%A6%AA%E0%A7%8D%E0%A6%B0%E0%A6%AB%E0%A7%81%E0%A6%B2%E0%A7%8D%E0%A6%B2%E0%A6%9A%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8D%E0%A6%B0%20%E0%A6%B0%E0%A6%BE%E0%A6%AF%E0%A6%BC%29%20009.tif?width=640$b$, $b$Chemist, University teacher, Essayist, Autobiographer$b$, $b$Jashore District$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Prafulla Roy$b$, DATE '1934-09-11', DATE '2025-06-19', $b$Prafulla Roy (11 September 1934 – 19 June 2025) was an Indian Bengali author, who lived in West Bengal. He received Bankim Puraskar and Sahitya Akademi Award for his literary contribution in Bengali.

