INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Pramatha Chaudhuri$b$, DATE '1868-08-07', DATE '1946-09-02', $b$Pramathanath Chaudhuri (7 August 1868 – 2 September 1946), known as Pramatha Chaudhuri, alias Birbal, was a Bengali essayist, poet, and writer. He was the nephew of Rabindranath Tagore as his mother was Sukumari Debi, the second sister of Tagore. He married musician and writer Indira Devi Chaudhurani, daughter of Satyendranath Tagore, the first Indian to have joined the Indian Civil Services and an author, composer and feminist, who was the second eldest brother of Rabindranath Tagore.

Notable works: Sonnet-panchashat
Education: Presidency University, Hare School, Krishnanagar Debnath High School, St. Xavier's College, Kolkata

Source: Wikipedia — https://en.wikipedia.org/wiki/Pramatha_Chaudhuri$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Photograph%20of%20Pramatha%20chaudhuri.jpg?width=640$b$, $b$Writer, Barrister, Editor, University teacher, Essayist, Poet$b$, $b$Pabna District$b$, $b$Kolkata$b$, 'day', 'day');
