INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shibdas Bandyopadhyay$b$, DATE '1932-12-27', DATE '2009-08-08', $b$শিবদাস বন্দ্যোপাধ্যায় (২৭ ডিসেম্বর ১৯৩২ – ৮ আগস্ট ২০০৯) একজন বিশিষ্ট বাঙালি কবি ও কালজয়ী গীতিকার ছিলেন। বিংশ শতাব্দীর দ্বিতীয়ার্ধ জুড়ে বাংলা ছায়াছবি ও আধুনিক গানের জগতে যাঁরা অসাধারণ গানের বাণী সাজিয়ে উপহার দিয়েছিলেন তাঁদের অন্যতম হলেন শিবদাস বন্দ্যোপাধ্যায়। তিনি বাংলা সঙ্গীতের তাবড়-তাবড় শিল্পীদের জন‍্যই লিখতেন। তাঁর গানের ছন্দ, তাল ও বাণীতে আজও মুগ্ধ বাঙালি।

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%B6%E0%A6%BF%E0%A6%AC%E0%A6%A6%E0%A6%BE%E0%A6%B8_%E0%A6%AC%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8D%E0%A6%AF%E0%A7%8B%E0%A6%AA%E0%A6%BE%E0%A6%A7%E0%A7%8D%E0%A6%AF%E0%A6%BE%E0%A6%AF%E0%A6%BC$b$, 'bn', NULL, $b$Lyricist$b$, $b$Khulna$b$, $b$Kolkata$b$, 'day', 'day');
