INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Dinesh Gangopadhyay$b$, DATE '1905-08-28', DATE '1984-07-13', $b$দীনেশ গঙ্গোপাধ্যায়(ইংরেজি: Dinesh Gangopadhyay) (২৮ আগস্ট,১৯০৫ - ১৩ জুলাই, ১৯৮৪) বাংলা সাহিত্যের কল্লোলযুগের অন্তিমপর্বের কবি ও বিভিন্ন কবিতা পত্রিকার নিয়মিত লেখক। তিরিশের দশকে 'বঙ্গশ্রী'পত্রিকায় প্রকাশিত তার কবিতাবলী বিশেষ সাড়া জাগিয়েছিল।

