INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Birendra Chattopadhyay$b$, DATE '1920-09-02', DATE '1985-07-11', $b$বীরেন্দ্র চট্টোপাধ্যায় (ইংরেজি: Birendra  Chattopadhyay; ২ সেপ্টেম্বর ১৯২০ — ১১ জুলাই ১৯৮৫) আধুনিক বাংলা সাহিত্যের অন্যতম খ্যাতনামা কবি। তাঁর কবিতায় ভাষিত হয়েছে সমগ্র দুনিয়ার প্রতারিত মানুষের বেদনা, মানবতা-বিরোধী ঘটনার বিরুদ্ধে বলিষ্ঠ তীব্র-প্রতিবাদ। অন্যদিকে রোমান্টিকের মতো সমাজ জীবনের সুন্দর স্বপ্নকে শেষমুহূর্ত পর্যন্ত রক্ষা করে গেছেন। তাঁর উল্লেখযোগ্য পুরস্কার রবীন্দ্র পুরস্কার

