INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$মোহাম্মদ মাহফুজ উল্লাহ$b$, DATE '1936-01-01', DATE '2013-12-29', $b$মোহাম্মদ মাহফুজ উল্লাহ (১ জানুয়ারি ১৯৩৬ – ২৯ ডিসেম্বর ২০১৩) বাংলাদেশের সাহিত্যিক, কবি ও সাংবাদিক যিনি বাংলা ভাষা আন্দোলন কর্মী ছিলেন। ভাষা ও সাহিত্যে বিশেষ অবদানের জন্য ২০০৭ সালে তিনি রাষ্ট্রের দ্বিতীয় সর্বোচ্চ বেসামরিক সম্মান একুশে পদক-এ ভূষিত হন।

