INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Jahidul Haque$b$, DATE '1949-08-11', DATE '2023-02-15', $b$জাহিদুল হক (১১ আগস্ট ১৯৪৯ -১৫ জানুয়ারি ২০২৪) বাংলাদেশের একজন আধুনিক বাংলা কবি, সাংবাদিক, গল্পকার, ঔপন্যাসিক ও গীতিকার ছিলেন। বাংলা কবিতায় বিশেষ অবদানের জন্য তিনি ২০০২ সালে বাংলা একাডেমি পুরস্কার পান।

