INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Minar Mahmud$b$, DATE '1959-01-01', DATE '2012-03-29', $b$মিনার মাহমুদ (জন্ম: ১০ মার্চ, ১৯৫৯ – মৃত্যু: ২৯ মার্চ, ২০১২) একজন বাঙালি সাংবাদিক, সম্পাদক ও লেখক, যিনি ১৯৮০-এর দশকে সামরিক শাসনবিরোধী সাংবাদিকতার জন্য বিশেষ পরিচিতি লাভ করেন। তিনি সাপ্তাহিক বিচিন্তা-এর প্রতিষ্ঠাতা, প্রকাশক ও সম্পাদক ছিলেন। হুসেইন মুহাম্মদ এরশাদ-এর সামরিক শাসনামলে তাঁর অনুসন্ধানী ও সমালোচনামূলক প্রতিবেদনের জন্য তিনি ব্যাপক আলোচিত হন। ব্যক্তিগত জীবনে তিনি লেখিকা তসলিমা নাসরিন-এর তৃতীয় স্বামী ছিলেন। দীর্ঘ প্রবাসজীবন শেষে দেশে ফিরে তিনি পুনরায় বিচিন্তা প্রকাশের উদ্যোগ নেন এবং দৈনিক আমাদের সময়-এ লেখালেখি করেন। ২০১২ সালের ২৯ মার্চ তিনি আত্মহত্যার মাধ্যমে মৃত্যুবরণ করেন।

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%AE%E0%A6%BF%E0%A6%A8%E0%A6%BE%E0%A6%B0_%E0%A6%AE%E0%A6%BE%E0%A6%B9%E0%A6%AE%E0%A7%81%E0%A6%A6$b$, 'bn', $b$https://commons.wikimedia.org/wiki/Special:FilePath/MinarMahmud2012.png?width=640$b$, $b$Journalist$b$, NULL, NULL, 'year', 'day');
