INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$সফিউদ্দিন আহমদ$b$, DATE '0941-10-19', DATE '2026-02-24', $b$সফিউদ্দিন আহমদ (জন্ম: ১৯ অক্টোবর, ১৯৪১ - মৃত্যু: ২৪ ফেব্রুয়ারি, ২০২৬) বাংলাদেশের প্রথিতযশা ভাষা ও সাহিত্য গবেষক ছিলেন। তিনি বাংলা সাহিত্য, তুলনামূলক সমালোচনা এবং বিশ্বসাহিত্যে পণ্ডিত; তথ্যসন্ধানী এবং সমাজমনস্ক ও প্রগতিশীল চিন্তাচেতনায় ঋদ্ধ একজন মৌলিক গবেষক। তার গবেষণা গ্রন্থ ডিরোজিও এবং ইয়ং বেঙ্গল মুভমেন্ট ও ডিরোজিও বাংলা গবেষণা সাহিত্যে একটি মৌলিক অবদান হিসাবে স্বীকৃতি। বাংলাদেশে উনিশ শতকের রেনেসাঁর বিশ্লেষণ ও গবেষণায় তার অবদান যুগস্রষ্টা হিসাবে স্বীকৃত। তার মতে চর্যাপদের ভাষা বাংলা নয়।

