INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$সাযযাদ কাদির$b$, DATE '1947-04-14', DATE '2017-04-06', $b$সাযযাদ কাদির (জন্ম: ১৪ এপ্রিল ১৯৪৭-৬ এপ্রিল ২০১৭) বাংলাদেশের একজন প্রখ্যাত সাহিত্যিক ও সাংবাদিক। তিনি বাংলা সাহিত্যের ষাটের দশকের অন্যতম কবি, গবেষক ও প্রাবন্ধিক হিসেবে পরিচিত।

