Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%B8%E0%A6%BE%E0%A6%AF%E0%A6%AF%E0%A6%BE%E0%A6%A6_%E0%A6%95%E0%A6%BE%E0%A6%A6%E0%A6%BF%E0%A6%B0$b$, 'bn', $b$https://commons.wikimedia.org/wiki/Special:FilePath/%E0%A6%B8%E0%A6%BE%E0%A6%AF%E0%A7%8D%E2%80%8C%E0%A6%AF%E0%A6%BE%E0%A6%A6%20%E0%A6%95%E0%A6%BE%E0%A6%A6%E0%A6%BF%E0%A6%B0.jpg?width=640$b$, $b$Poet$b$, NULL, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Tahir Zaman Priyo$b$, DATE '1997-03-07', DATE '2024-07-19', $b$তাহির জামান প্রিয় ছিলেন বাংলাদেশের একজন ফ্রিল্যান্স সাংবাদিক ও ভিডিওগ্রাফার। তিনি দ্য রিপোর্ট.লাইভ নামক অনলাইন নিউজ পোর্টালে ভিডিও জার্নালিস্ট হিসেবে যুক্ত ছিলেন। ২০২৪ সালের ১৯ জুলাই রাজধানীর ধানমন্ডি সেন্ট্রাল রোডে কোটা সংস্কার আন্দোলনের সংবাদ সংগ্রহের সময় মাথায় গুলিবিদ্ধ হয়ে নিহত হন। তার এই হত্যাকাণ্ড বাংলাদেশের সাংবাদিকদের নিরাপত্তা নিয়ে উদ্বেগ বাড়িয়ে তোলে এবং আন্তর্জাতিকভাবে এর নিন্দা জানানো হয়। ইউনেস্কোর ডিরেক্টর জেনারেল ক্লেয়ার ও'হ্যাগান বিবৃতি দিয়ে এই হত্যাকাণ্ডের নিন্দা জানান। এছাড়াও এশিয়ান হিউম্যান রাইটস ডিফেন্ডার নামক সংগঠন এই হত্যাকাণ্ডটি বিবৃতি প্রদান করে। রিপোর্টারস উইথআউট বর্ডার নামক সংগঠন প্রিয়সহ অন্যান্য সাংবাদিক হত্যা নিয়ে বিবৃতি প্রদান করে।

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%A4%E0%A6%BE%E0%A6%B9%E0%A6%BF%E0%A6%B0_%E0%A6%9C%E0%A6%BE%E0%A6%AE%E0%A6%BE%E0%A6%A8_%E0%A6%AA%E0%A7%8D%E0%A6%B0%E0%A6%BF%E0%A6%AF%E0%A6%BC$b$, 'bn', NULL, $b$Freelance journalist, Videographer, Journalist$b$, $b$Rangpur$b$, $b$Dhanmondi Thana$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Fazlul Haque$b$, DATE '1930-05-26', DATE '2003-10-26', $b$ফজলুল হক (২৬ মে ১৯২২-২৬ অক্টোবর ২০০৩) একজন বাংলাদেশী চলচ্চিত্র পরিচালক, প্রযোজক ও সাংবাদিক ছিলেন। তিনি বাংলাদেশের প্রথম চলচ্চিত্র বিষয়ক পত্রিকা সিনেমার সম্পাদক ও প্রথম শিশু চলচ্চিত্র ‘প্রেসিডেন্ট’-এর পরিচালক ছিলেন।

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%AB%E0%A6%9C%E0%A6%B2%E0%A7%81%E0%A6%B2_%E0%A6%B9%E0%A6%95_%28%E0%A6%9A%E0%A6%B2%E0%A6%9A%E0%A7%8D%E0%A6%9A%E0%A6%BF%E0%A6%A4%E0%A7%8D%E0%A6%B0_%E0%A6%AA%E0%A6%B0%E0%A6%BF%E0%A6%9A%E0%A6%BE%E0%A6%B2%E0%A6%95%29$b$, 'bn', NULL, $b$Film director, Producer, Journalist$b$, $b$Bogura$b$, $b$Dhaka$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$মাহফুজুর রহমান$b$, DATE '1935-01-01', DATE '2017-11-16', $b$মাহফুজুর রহমান (আনু. ১৯৩৫-১৬ নভেম্বর ২০১৭) বাংলাদেশের প্রাক্তন সরকারি কর্মকর্তা, সাহিত্যিক ও অর্থনীতিবিদ যিনি পরিকল্পনা কমিশনের সদস্য এবং জাতিসংঘের শীর্ষস্থানীয় অর্থনীতিবিদ থেকে অবসরগ্রহণ করেন। ভ্রমণকাহিনী সাহিত্যে অবদানের জন্য তিনি ২০১৩ সালে বাংলা একাডেমি পুরস্কার লাভ করেন।

Awards: Bangla Academy Literary Award
Education: University of Manchester, University of Dhaka

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%AE%E0%A6%BE%E0%A6%B9%E0%A6%AB%E0%A7%81%E0%A6%9C%E0%A7%81%E0%A6%B0_%E0%A6%B0%E0%A6%B9%E0%A6%AE%E0%A6%BE%E0%A6%A8_%28%E0%A6%B8%E0%A6%BE%E0%A6%B9%E0%A6%BF%E0%A6%A4%E0%A7%8D%E0%A6%AF%E0%A6%BF%E0%A6%95%29$b$, 'bn', NULL, $b$Writer$b$, $b$Naogaon$b$, $b$New York$b$, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$রেজওয়ান সিদ্দিকী$b$, DATE '1953-02-10', DATE '2024-01-16', $b$রেজওয়ান হোসেন সিদ্দিকী (১০ ফেব্রুয়ারি ১৯৫৩ - ১৬ জানুয়ারি ২০২৪) বাংলাদেশি সাংবাদিক ও সব্যসাচি লেখক। ১৯৯১ সালে খালেদা জিয়া প্রধানমন্ত্রী থাকাকালিন সময়ে তার ডেপুটি প্রেস সেক্রেটারি ছিলেন। ২০০১ সালে প্রেস ইনস্টিটিউট বাংলাদেশ -এর মহাপরিচালক হিসেবে নিযুক্ত হয়ে ৪ বছর দায়িত্ব পালন করেন। সর্বশেষ তিনি ঢাকা থেকে প্রকাশিত দৈনিক দিনকালের ভারপ্রাপ্ত সম্পাদক হিসেবে দায়িত্ব পালন করেন।

Education: University of Dhaka

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%B0%E0%A7%87%E0%A6%9C%E0%A6%93%E0%A6%AF%E0%A6%BC%E0%A6%BE%E0%A6%A8_%E0%A6%B8%E0%A6%BF%E0%A6%A6%E0%A7%8D%E0%A6%A6%E0%A6%BF%E0%A6%95%E0%A7%80$b$, 'bn', NULL, $b$Newspaper editor, Writer$b$, NULL, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$বাশার মাহমুদ$b$, DATE '1952-05-01', DATE '2021-09-26', $b$বাশার মাহমুদ (১৯৫২ - ২০২১) ছিলেন বহুমুখী প্রতিভার অধিকারী একজন বাংলাদেশি সাংস্কৃতিক ব্যক্তিত্ব। তিনি ছিলেন একাধারে কবি, সাহিত্যিক, নাট্যকার, সাংবাদিক ও ইতিহাস গবেষক। পেশায় ছিলেন শিক্ষক। বিংশ শতাব্দীর শেষভাগে স্বাধীনতা-উত্তর বাংলাদেশে সাংস্কৃতিক অঙ্গনে তার অবদান অনস্বীকার্য। নাট্যকলায় সামগ্রিক অবদানের স্বীকৃতিস্বরূপ ২০১৫ খ্রিষ্টাব্দে জেলা শিল্পকলা একাডেমি পদক এবং সাহিত্যে ২০১১ খ্রিষ্টাব্দে সুনীল সাহিত্য পুরস্কারে ভূষিত হয়েছেন।

Awards: Sunil Literary Award, Shilpakala Padak

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%AC%E0%A6%BE%E0%A6%B6%E0%A6%BE%E0%A6%B0_%E0%A6%AE%E0%A6%BE%E0%A6%B9%E0%A6%AE%E0%A7%81%E0%A6%A6_%28%E0%A6%95%E0%A6%AC%E0%A6%BF%29$b$, 'bn', NULL, $b$Playwright, Teacher, Poet$b$, NULL, NULL, 'day', 'day');
