INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Sheikh Chand$b$, DATE '1650-01-01', DATE '1725-01-01', $b$শেখ চাঁদ  বা শেখ চান্দ (আনু. ১৬৫০-১৭২৫) মধ্যযুগীয় বাংলা সাহিত্যের একজন উল্লেখযোগ্য কবি ও অনুবাদক। তিনি বর্তমান কুমিল্লা অঞ্চলে ১৬৫০ সালে জন্মগ্রহণ করেন। তিনি রসুল বিজয় নামক কাব্যগ্রন্থ লিখে প্রচুর জনপ্রিয় হয়েছিলেন। এছাড়াও তিনি তালিবনামা, হরগৌরী সম্বাদ নামে আরো দুটি কাব্যগ্রন্থ রচনা করেছিলেন। কবির পিতার নাম ফাতেহ মুহাম্মদ, তিনি নওয়াব আলী নামক একজন পণ্ডিতের নিকট শিক্ষা গ্রহন এবং শাহ দৌলাহ নামক একজন পীরের নিকট বাইয়াত গ্রহন করেছিলেন।

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%B6%E0%A7%87%E0%A6%96_%E0%A6%9A%E0%A6%BE%E0%A6%81%E0%A6%A6$b$, 'bn', NULL, $b$Poet, Philosopher, Translator, Writer, Biographer$b$, $b$Cumilla$b$, NULL, 'year', 'year');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Debipada Bhattacharya$b$, DATE '1912-01-01', DATE '1989-04-22', $b$ড.দেবীপদ ভট্টাচার্য ( ১ জানুয়ারি ১৯১২ – ২২ এপ্রিল ১৯৮৯) ছিলেন একজন ভারতীয় বাঙালি কবি, প্রাবন্ধিক, সমালোচক ও শিক্ষাব্রতী। রবীন্দ্র গবেষক ও বিশেষজ্ঞ হিসাবেও তার পরিচিতি ছিল।

