INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$হাসান মেহেদী$b$, DATE '1984-01-01', DATE '2024-07-18', $b$হাসান মেহেদী ছিলেন অনলাইন গণমাধ্যম ঢাকা টাইমস ২৪-এর সংবাদকর্মী। ২০২৪ সালের ১৮ জুলাই বিকেলে পেশাগত দায়িত্ব পালন করার সময় কোটা সংস্কার আন্দোলনকারী ও পুলিশের মধ্যে সংঘর্ষ চলাকালে পুলিশের ছোড়া ছররা গুলির আঘাতে মৃত্যুবরণ করেন তিনি। তার মৃত্যুর ঘটনাটি ছড়িয়ে গেলে সাংবাদিকদের নিরাপত্তা নিয়ে উদ্বেগের জন্ম দেয় এবং এই হত্যাকাণ্ডের প্রতি গণমাধ্যম ও সাধারণ মানুষের পক্ষ থেকে নিন্দা জানানো হয়।

