INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Kuntal Biswas$b$, DATE '1946-08-09', DATE '2012-01-15', $b$কুন্তল বিশ্বাস (জন্ম: ৯ আগস্ট, ১৯৪৬ - মৃত্যু: ১৫ জানুয়ারি, ২০১২) বাংলাদেশের রাজনীতিক, সাংবাদিক ও মুক্তিযোদ্ধা। তিনি বাংলাদেশের কমিউনিস্ট পার্টির (সিপিবি) নেত্রকোণা জেলা কমিটির সম্পাদকমণ্ডলীর সদস্য ছিলেন। তিনি জেলা সিপিবির সাবেক সম্পাদক ছাড়াও উদীচী শিল্পী গোষ্ঠী, রবীন্দ্র সঙ্গীত সন্মিলন পরিষদ, জেলা শিল্পকলা একাডেমীর সদস্য ছিলেন।

