INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Gouri Shankar Bhattacharya$b$, DATE '1799-01-01', DATE '1859-02-05', $b$গৌরীশঙ্কর ভট্টাচার্য, তর্কবাগীশ (১৭৯৯ – ৫ ফেব্রুয়ারি ১৮৫৯) ঊনবিংশ শতকের একজন সাংবাদিক, সম্পাদক এবং লেখক ছিলেন।  তিনি ১৮৩৬ খ্রিষ্টাব্দে ভারতের প্রথম রাজনৈতিক সংগঠন বঙ্গভাষা প্রকাশিকা সভার অন্যতম প্রতিষ্ঠাতা ছিলেন এবং তিনি এর প্রথম সভাপতি হিসেবে দায়িত্ব পালন করেন।

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%97%E0%A7%8C%E0%A6%B0%E0%A7%80%E0%A6%B6%E0%A6%99%E0%A7%8D%E0%A6%95%E0%A6%B0_%E0%A6%AD%E0%A6%9F%E0%A7%8D%E0%A6%9F%E0%A6%BE%E0%A6%9A%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%AF$b$, 'bn', NULL, $b$Writer, Editor$b$, $b$Moulvibazar District$b$, NULL, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Mohiuddin$b$, DATE '1906-01-01', DATE '1975-02-12', $b$মহীউদ্দিন (জানুয়ারি, ১৯০৬ - ১২ ফেব্রুয়ারি, ১৯৭৫) বিংশ শতাব্দীর একজন সাম্যবাদী ধারার কবি। নির্যাতিত, বুভুক্ষু ও দারিদ্র পীড়িত মানুষের মুক্তির বাণী তার কবিতায় স্বতঃস্ফূর্তভাবে প্রকাশিত। বঞ্চিত ও শোষিত জনগণকে বৈপ্লবিক চিন্তাধারায় উদ্বুদ্ধ করাই ছিল তার সাহিত্য সাধনার মূল লক্ষ্য। তার 'কামিনীকাঞ্চন' উপন্যাস এবং 'অন্ন চাই, আলো চাই' পত্রিকা রাষ্ট্রদ্রোহিতার অভিযোগে পাকিস্তান সরকার কর্তৃক বাজেয়াপ্ত হয়। তিনি কাজী নজরুল ইসলামের মতাদর্শের অনুসারী কবি হিসেবে পরিচিত ছিলেন। সাহিত্যকর্মের জন্য ১৯৬২ সালে প্রেসিডেন্টের 'প্রাইড অব পারফরমেন্স' পুরস্কার লাভ করেন। স্বাধীনতা পূর্বকালে তিনি শ্রমিক আন্দোলনের সঙ্গে যুক্ত ছিলেন।

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%AE%E0%A6%B9%E0%A7%80%E0%A6%89%E0%A6%A6%E0%A7%8D%E0%A6%A6%E0%A6%BF%E0%A6%A8$b$, 'bn', NULL, $b$Poet, Writer, Politician, Editor, Translator, Novelist$b$, $b$Dohar Upazila$b$, $b$Dhaka$b$, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Radha Gobinda Basak$b$, DATE '1885-01-08', DATE '1982-12-10', $b$ডক্টর রাধাগোবিন্দ বসাক (৮ জানুয়ারি ১৮৮৫ - ১০ ডিসেম্বর ১৯৮২) ছিলেন প্রখ্যাত বাঙালি ইতিহাসবিদ ও ভাষা-বিজ্ঞানী। ঢাকা বিশ্ববিদ্যালয় প্রতিষ্ঠাকালীন যেসকল ব্যক্তি এখানে যোগদান করেন তিনি ছিলেন তাদের অন্যতম; তিনি এবং ডক্টর মুহম্মদ শহীদুল্লাহ প্রতিষ্ঠাকালীন সময়ে ঢাকা বিশ্ববিদ্যালয়ে বাংলা বিভাগের লেকচারার হিসেবে যোগ দান করেন।

Notable works: Pal-samrajyer Shashan-pranali

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%B0%E0%A6%BE%E0%A6%A7%E0%A6%BE%E0%A6%97%E0%A7%8B%E0%A6%AC%E0%A6%BF%E0%A6%A8%E0%A7%8D%E0%A6%A6_%E0%A6%AC%E0%A6%B8%E0%A6%BE%E0%A6%95$b$, 'bn', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Radha%20Gobinda%20Basak.png?width=640$b$, $b$Writer, Teacher$b$, $b$Rajshahi$b$, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Rebati Mohan Burman$b$, DATE '1905-01-01', DATE '1952-05-06', $b$রেবতী মোহন বর্মণ (১৯০৫ - ৬ মে, ১৯৫২) বিংশ শতাব্দীর একজন সাম্যবাদী ধারার লেখক ও ভারতের স্বাধীনতা আন্দোলনকারী বিপ্লবী। তিনি বেশ কিছু পুস্তক রচনা করে বাংলাদেশ অঞ্চলে মার্কসবাদের বিকাশে গুরুত্বপূর্ণ অবদান রাখেন।

Education: University of Calcutta

