INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Washiqur Rahman Babu$b$, DATE '1988-06-01', DATE '2015-03-30', $b$বাংলাদেশের মাটিতে ২০১৩ খ্রিষ্টাব্দ থেকে একাধিক ধর্মনিরপেক্ষ নাস্তিক, লেখক, ব্লগার ও প্রকাশক সন্ত্রাসবাদীদের হাতে নিহত বা গুরুতর আহত হয়েছেন। এই আক্রমণের ঘটনাগুলির সম্ভাব্য কারণ হল বাংলাদেশের সেইসময়কার দ্বন্দ্ব। বলা হয় এর এক দিকে ছিলেন ধর্মনিরপেক্ষ জনসমাজ, যারা বাংলাদেশের ধর্মনিরপেক্ষতার ঐতিহ্য বজায় রাখতে চান, ও অন্যদিকে ছিলেন ইসলামবাদী জনসমাজ, যারা বাংলাদেশকে ইসলামী রাষ্ট্র হিসেবে দেখতে চান। তৎকালীন যুদ্ধাপরাধ ট্রাইবুনালের বিচারকাজগুলি, যেগুলিতে সাম্প্রতিক অতীতের বিরোধী দল জামায়াতে ইসলামীর অনেক নেতাকে ১৯৭১ সালে বাংলাদেশের রক্তক্ষয়ী স্বাধীনতা যুদ্ধে সংঘটিত অপরাধের কারণে দোষী সাব্যস্ত করা হয়েছিল, সেগুলিও এই দ্বন্দ্বের তীব্রতা বৃদ্ধি করেছে।

প্রথমদিকে এইসব হত্যাকাণ্ড ধর্মনিরপেক্ষ লেখকদের উপর হলেও, ধীরে ধীরে ইসলামী সন্ত্রাসবাদ অন্যান্য লক্ষবস্তুতে আক্রমণ করে। সমকামী অধিকারকর্মী, বাউল সাধক, শিক্ষক, হিন্দু পুরোহিত ,বৌদ্ধ ভান্তে, প্রভৃতিরা চরমপন্থীদের লক্ষ্যবস্তুতে পরিণত হয়। এছাড়াও ইসলামী সন্ত্রাসবাদীরা হামলার শিকার হয় মাজারের খাদেম, শিয়া সম্প্রদায়ের বিশিষ্ট ব্যক্তি, আহমদীয়া ইমাম, এবং সুফি সাধকও। শিয়া সম্প্রদায়ের মিছিলে  এবং ঈদের পরে দেশের বৃহত্তর জামাত হওয়া শোলাকিয়ার ময়দানেও তারা হামলা করে। রাষ্ট্রের ঊর্ধ্বতন কর্মকর্তারা প্রথমদিকে এইসব হত্যাকাণ্ডের জন্য খোদ হত্যার স্বীকার হওয়া ব্যক্তিদেরই দায়ী করলেও  পরবর্তীতে হলি আর্টিজানে বিশজন বিদেশী নাগরিকের মৃত্যুর  পর প্রশাসন কিছুটা সতর্ক হয়, এরপর জঙ্গীবিরোধী বেশ কিছু অভিযান চালিয়ে বেশ কয়েকজনকে আটক করে।

বাংলাদেশ সরকার ধর্মীয় সম্প্রদায়ভুক্ত গোষ্ঠী ও জনসাধারণের দাবি অনুসারে ধর্মনিরপেক্ষ ব্লগারদেরই গ্রেফতার শুরু করে। একারণে বাংলদেশ সরকার তীব্র সমালোচনার মুখে পড়ে। ২০১৬ সালের ১৮ জুন থেকে, বাংলাদেশ পুলিশ কথিত জঙ্গি গ্রেফতারের অভিযান চালিয়ে একসপ্তাহের ভিতরে প্রায় এগারো হাজার মানুষকে গ্রেফতার করা শুরু করে। রাষ্ট্রের একাজটিও সমালোচনার মুখে পড়ে।

এর কিছুদিন পরে ২০১৬ সালের ২ জুলাই, মোট ৪৮ জন লোক, যাদের মধ্যে ২০ জন অন্য দেশের নাগরিক ছিলেন, তারা এক জঙ্গি হামলায় নিহত হয়।

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%93%E0%A6%AF%E0%A6%BC%E0%A6%BE%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%81%E0%A6%B0_%E0%A6%B0%E0%A6%B9%E0%A6%AE%E0%A6%BE%E0%A6%A8_%E0%A6%AC%E0%A6%BE%E0%A6%AC%E0%A7%81$b$, 'bn', NULL, $b$Blogger, Journalist$b$, NULL, $b$Dhaka$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shishir Nag$b$, DATE '1936-01-01', DATE '1960-01-01', $b$শিশির নাগ (১৯৩৬ - ৭ জুলাই, ১৯৬০) ছিলেন বাঙালি সাংবাদিক এবং বিপ্লবী কমিউনিস্ট পার্টির সাবেক নেতা। নওগাঁ শহরের অন্যতম ট্রেড ইউনিয়ন সংগঠক, একাধিক বাংলা দৈনিক ও সাপ্তাহিক পত্রিকার স্বাধীন সংবাদদাতা এবং স্থানীয় উদ্বাস্তু সমিতির সম্পাদক ছিলেন। উদ্বাস্তুদের দাবি আদায়ের আন্দোলনে যোগ দিয়ে দুবার কারাদণ্ড ভোগ করেন। ভারতের অসমের ভ্রাতৃঘাতী সংঘর্ষকালে দাঙ্গা রুখতে গিয়ে তিনি নিহত হন।

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%B6%E0%A6%BF%E0%A6%B6%E0%A6%BF%E0%A6%B0_%E0%A6%A8%E0%A6%BE%E0%A6%97$b$, 'bn', NULL, $b$Revolutionary, Politician, Journalist$b$, $b$Naogaon District$b$, $b$Assam$b$, 'year', 'year');
