INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Jab-Un-Nesa Jamal$b$, DATE '1926-12-27', DATE '1995-04-01', $b$জেব-উন-নেসা জামাল (২৭ ডিসেম্বর, ১৯২৬ - ১ এপ্রিল ১৯৯৫) ছিলেন বাংলা ভাষার গীতিকার। তিনি ঢাকা বেতারের কণ্ঠশিল্পী, কথিকা পাঠক ও অনুষ্ঠান পরিচালক ছিলেন। তিনি বেতারের মহিলা মাহফিল, স্কুল ব্রডকাস্ট, বুনিয়াদি গণতন্ত্রের আসর ইত্যাদি অনুষ্ঠান পরিচালনা করেন। গীতিকার হিসেবে খ্যাতি অর্জন করেন। প্রেমমূলক, দেশাত্মবোধক ও মরমি গান রচনায় পারদর্শিতার পরিচয় দেন।

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%9C%E0%A7%87%E0%A6%AC-%E0%A6%89%E0%A6%A8-%E0%A6%A8%E0%A7%87%E0%A6%B8%E0%A6%BE_%E0%A6%9C%E0%A6%BE%E0%A6%AE%E0%A6%BE%E0%A6%B2$b$, 'bn', NULL, $b$Writer$b$, $b$Rajshahi$b$, $b$Dhanmondi Thana$b$, 'day', 'day');
