INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Bhupendra Kishore Rakshit Roy$b$, DATE '1902-03-19', DATE '1972-04-24', $b$ভূপেন্দ্রকিশোর রক্ষিত রায় (১৯ মার্চ,১৯০২ - ২৪ এপ্রিল,১৯৭২) ছিলেন ভারতীয় উপমহাদেশের ব্রিটিশ বিরোধী স্বাধীনতা আন্দোলনের একজন অন্যতম ব্যক্তিত্ব এবং অগ্নিযুগের বিপ্লবী। তিনি ছিলেন একজন রাজনীতিবিদ ও লেখক। তিনি ফরোয়ার্ড ব্লকপন্থী রাজনৈতিক নেতা এবং পশ্চিমবঙ্গের রাজ্য সভার সদস্য ছিলেন।

