INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Muhammad Abdur Rashid Siddiqui$b$, DATE '1894-01-01', DATE '1950-03-26', $b$মোহাম্মদ আবদুর রশিদ সিদ্দিকী (১৮৯৪–১৯৫১) ছিলেন একজন সাহিত্যিক, ভাষা-গবেষক, সাংবাদিক ও রাজনীতিবিদ। তিনি বাংলা ভাষা ও সাহিত্যের পাশাপাশি চট্টগ্রামী ভাষা গবেষণায় অবদান রাখেন। সাহিত্য, সাংবাদিকতা ও রাজনীতিতে তাঁর সক্রিয় অংশগ্রহণের পাশাপাশি তিনি একাধিক সাময়িকপত্র সম্পাদনা ও প্রকাশ করেন। তাঁর রচনার মধ্যে কাব্য, উপন্যাস, গবেষণা, প্রবন্ধ, জীবনী, আত্মজীবনী ও অনুবাদগ্রন্থ উল্লেখযোগ্য।

