INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Anwar Hossain$b$, DATE '1930-01-01', DATE '1950-01-01', $b$একই নামের অন্যান্য ব্যক্তিবর্গের জন্য দেখুন আনোয়ার হোসেন।

আনোয়ার হোসেন (১৯৩০ - ২৪ এপ্রিল, ১৯৫০) একজন বাংলাদেশের ছাত্র আন্দোলন, তেভাগা আন্দোলন, সাম্যবাদী আন্দোলনের নেতা, কুশলী তার্কিক, শিল্প-সাহিত্যে আগ্রহী একজন শহীদ বিপ্লবী। ১৯৫০ সালের ২৪ এপ্রিল রাজশাহীর খাপড়া ওয়ার্ড গণহত্যায় পুলিশ জেলের ভেতরে আরও ছয়জন রাজবন্দীর সঙ্গে তাকেও হত্যা করে। রণেশ দাশগুপ্ত তাঁর দ্বিতীয় গ্রন্থ আলো দিয়ে আলো জ্বালা উৎসর্গ করেন আনোয়ার হোসেনকে।

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%86%E0%A6%A8%E0%A7%8B%E0%A6%AF%E0%A6%BC%E0%A6%BE%E0%A6%B0_%E0%A6%B9%E0%A7%8B%E0%A6%B8%E0%A7%87%E0%A6%A8_%28%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0_%E0%A6%A8%E0%A7%87%E0%A6%A4%E0%A6%BE%29$b$, 'bn', NULL, $b$Politician, Lyricist, Singer$b$, $b$Khulna$b$, NULL, 'year', 'year');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Hosne Ara$b$, DATE '1916-01-01', DATE '1999-03-30', $b$হোসনে আরা (১৯১৬- ৩০ মার্চ ১৯৯৯) বাংলাদেশের একজন জনপ্রিয় সাহিত্যিক যিনি ছড়াকার হিসেবে অধিক জনপ্রিয়। তার লিখিত সফদর ডাক্তার কবিতাটি চল্লিশের দশকে ব্যাপক জনপ্রিয়তা অর্জন করে এবং বর্তমানেও জনপ্রিয়।  একসময়ে কবিতাটি বাংলাদেশে পাঠ্য হিসেবে বাংলা বইয়ে পঠিত হতো।

Awards: Bangla Academy Literary Award

