INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Gokulanada Gitiswami$b$, DATE '1886-11-26', DATE '1962-07-10', $b$গোকুলানন্দ গীতিস্বামী (নভেম্বর ২৬, ১৮৯৬ - জুলাই ১০, ১৯৬২) বিষ্ণুপ্রিয়া মণিপুরী সাহিত্যের অন্যতম পথিকৃৎ। তিনিই সর্বপ্রথম বিষ্ণুপ্রিয়া মণিপুরীদের ভেতর জাতীয়তাবোধ ও মাতৃভাষার প্রতি চেতনা জাগ্রত করেন। গোকুলানন্দ মুলত ছিলেন একজন চারণকবি। তৎকালীন মণিপুরী সমাজের শিক্ষিত একটি বৃহদাংশ যখন সাহেবি এবং বাঙালি চালচলন রপ্ত করতে ব্যস্ত, ঠিক সেই সময় মাতৃভাষায় নানান কবিতা, গান, গীতিপালা লিখে সেগুলোর পরিবেশনা নিয়ে ঘুরতেন গ্রাম থেকে গ্রামে। নিজস্ব ভাষা সংস্কৃতি আচার নিয়ম সবকিছু বিস্মৃত হয়ে এই সমাজ যখন প্রায় নিশ্চিহ্ন হবার দ্বারপ্রান্তে, তখন গীতিস্বামী সক্রেটিসের মতো নতুন আশার, নতুন সম্ভাবনার বাণী ঘরে ঘরে ফেরী করে বেড়িয়েছেন ক্লান্তিহীনভাবে। তিনি দেখিয়ে দিলেন, এই ভাষা এই সংষ্কৃতির ভেতরেও বিপুল সম্ভাবনা রয়েছে। শুধুমাত্র লোকমুখে প্রচারিত এই দরিদ্র ভাষাটি দিয়েও রচিত হতে পারে উৎকৃষ্ট সাহিত্য, শিল্পরস।

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%97%E0%A7%8B%E0%A6%95%E0%A7%81%E0%A6%B2%E0%A6%BE%E0%A6%A8%E0%A6%A8%E0%A7%8D%E0%A6%A6_%E0%A6%97%E0%A7%80%E0%A6%A4%E0%A6%BF%E0%A6%B8%E0%A7%8D%E0%A6%AC%E0%A6%BE%E0%A6%AE%E0%A7%80$b$, 'bn', NULL, $b$Writer, Poet$b$, $b$Bangladesh$b$, $b$Tripura$b$, 'day', 'day');
