INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Govinda Chandra Ray$b$, DATE '1838-10-23', DATE '1917-07-10', $b$গোবিন্দচন্দ্র রায় ( ২৩ অক্টোবর ১৮৩৮ - ১০ জুলাই ১৯১৭)  ছিলেন ঊনবিংশ শতকের বাংলা কবিদের একজন। পেশায় চিকিৎসক হয়েও, কবি হিসাবে বিশেষ প্রসিদ্ধি লাভ করেন।

