INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Chittaranjan Deb$b$, DATE '1924-03-28', DATE '2010-06-13', $b$চিত্তরঞ্জন দেব (২৮ মার্চ ১৯২৪ - ১৩ জুন ২০১০) রবীন্দ্রনাথ ঠাকুরের উপর গবেষক ছিলেন। তিনি একজন কবি, প্রাবন্ধিক ছিলেন। তিনি শান্তিনিকেতনে থাকতেন। তাকে 'রবীন্দ্র সংস্কৃতি পরিষদ', তার জীবনব্যাপী কাজ ও সাহিত্য ক্ষেত্রের অবদানসমূহের জন্য 'রবীন্দ্র তত্ত্বাচার্য' উপাধি দেয়।

Education: University of Calcutta, Visva-Bharati University

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%9A%E0%A6%BF%E0%A6%A4%E0%A7%8D%E0%A6%A4%E0%A6%B0%E0%A6%9E%E0%A7%8D%E0%A6%9C%E0%A6%A8_%E0%A6%A6%E0%A7%87%E0%A6%AC$b$, 'bn', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Chittaranjan%20Deb%2C%20writing%20an%20article%20at%20his%20Santiniketan%20house%20balcony.jpg?width=640$b$, $b$Writer$b$, $b$Sylhet$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Tarakishore Choudhury$b$, DATE '1859-06-10', DATE '1935-11-08', $b$সন্তদাস কাঠিয়াবাবা (১০ জুন ১৮৫৯ - ৮ নভেম্বর ১৯৩৫) পূর্বাশ্রমের নাম তারাকিশোর চৌধুরী। ঊনবিংশ শতকের এক প্রখ্যাত ভারতীয় বাঙালি যোগসাধক, দার্শনিক, ধর্মগুরু এবং বেদান্ত দ্বৈত-দ্বৈতবাদী রামদাস কাঠিয়াবাবার প্রধান শিষ্য। নিম্বার্ক সম্প্রদায় গুরু পরম্পরা ৫৫তম আচার্য্য, সাবেক কুম্ভ মেলার প্রেসিডেন্ট মহন্ত ও আধ্যাত্মিক নেতা ছিলেন। বিশ্বের সকল দেশে নিম্বার্কভাবধারার পুনর্জাগরণের জন্য প্রতিষ্ঠা করেছিলেন বহু নিম্বার্ক মন্দির ও আশ্রম।

Education: Vidyasagar College, Presidency University, University of Calcutta

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%B8%E0%A6%A8%E0%A7%8D%E0%A6%A4%E0%A6%A6%E0%A6%BE%E0%A6%B8_%E0%A6%95%E0%A6%BE%E0%A6%A0%E0%A6%BF%E0%A6%AF%E0%A6%BC%E0%A6%BE%E0%A6%AC%E0%A6%BE%E0%A6%AC%E0%A6%BE$b$, 'bn', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Santadas%20Kathiababa%20Maharaj%20India%20Vrindavan%20at%20Kathiababa%20Temple%201925.jpg?width=640$b$, $b$Spiritual leader, Monk, Philosopher, Writer, Poet, Teacher$b$, $b$Sylhet District$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shailabala Ghoshjaya$b$, DATE '1894-03-02', DATE '1974-09-21', $b$শৈলবালা ঘোষজায়া (২ মার্চ, ১৮৯৪ - ২১ সেপ্টেম্বর, ১৯৭৪) একজন খ্যাতনামা বাঙালি সাহিত্যিক। বাংলায় বহু উপন্যাস, ছোটগল্প রচনা করেছিলেন তিনি।

