INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Gour Gobinda Roy$b$, DATE '1841-01-01', DATE '1912-01-01', $b$গৌরগোবিন্দ রায়, উপাধ্যায়, (জন্ম: ১৮৪১ - মৃত্যু: ১৯১২) একজন গ্রন্থকার, ব্রাহ্মধর্মের উল্লেখযোগ্য ব্যক্তিত্ব এবং পত্রিকা সম্পাদক।

গৌরগোবিন্দ রায় বর্তমান বাংলাদেশের পাবনার ঘোড়াচরার নিবাসী ছিলেন । তার পিতার নাম গৌরমোহন । তার খুল্লতাত তাকে পোষ্যপুত্র নিয়েছিলেন । তিনি রংপুর হাইস্কুলে এন্ট্রান্স পর্যন্ত পড়েন । তারপর সংস্কৃত এবং ফারসী এবং এক মুসলমান সাধুর কাছে দরশ শিক্ষা করেন ।

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%97%E0%A7%8C%E0%A6%B0%E0%A6%97%E0%A7%8B%E0%A6%AC%E0%A6%BF%E0%A6%A8%E0%A7%8D%E0%A6%A6_%E0%A6%B0%E0%A6%BE%E0%A6%AF%E0%A6%BC$b$, 'bn', NULL, $b$Writer$b$, $b$Pabna$b$, $b$Kolkata$b$, 'year', 'year');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Kiran Shankar Sengupta$b$, DATE '1918-02-02', DATE '1998-05-01', $b$কিরণশঙ্কর  সেনগুপ্ত     (ইংরেজি: Kiranshankar  Sengupta) (২ ফেব্রুয়ারি, ১৯১৮ —  ১ মে,১৯৯৮) বিশ শতকের চল্লিশের দশকে সেসমস্ত তরুণ কবি বাংলা আধুনিক কবিতায় নতুন পথের সূচনা করেন তাঁদের অন্যতম কবি  ছিলেন। ইংরেজি সাহিত্যে পড়াশোনা করেও তিনি কলকাতা কেন্দ্রিক আধুনিক সাহিত্যের বাইরে গিয়ে মূলত তৎকালীন পূর্ব বাংলার নিজস্ব প্রগতিশীল সাহিত্যের ধারক ও বাহক ছিলেন।

