INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Satyananda Das$b$, DATE '1863-01-01', DATE '1942-01-01', $b$সত্যানন্দ দাশ (১৮৬৩–১৯৪২) একজন বাঙালি স্কুলশিক্ষক, প্রবন্ধকার, সমাজসেবক ও ব্রাহ্ম ধর্ম প্রচারক ছিলেন। তিনি প্রখ্যাত বাঙালি কবি জীবনানন্দ দাশ এর বাবা ও কবি কুসুমকুমারী দাশ এর স্বামী। তিনি ব্রজমোহন বিদ্যালয়ের সহকারী প্রধান শিক্ষক হিসেবে দীর্ঘসময় দায়িত্ব পালন করেন এবং বরিশাল ব্রাহ্মসমাজের সম্পাদক ও উপাচার্য ছিলেন। এছাড়াও তিনি ব্রহ্মবাদী পত্রিকার প্রতিষ্ঠাতা সম্পাদক ছিলেন। ধর্ম, নীতি, শিক্ষা ও সমাজ-বিষয়ে তার বহু রচনা ব্রহ্মবাদী, তত্ত্বকৌমুদী, প্রবাসী প্রভৃতি পত্রিকায় নিয়মিত প্রকাশিত হত।

