INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Siddique Ahmad$b$, DATE '1903-01-01', DATE '1987-05-19', $b$ছিদ্দিক আহমদ (১৯০৩ — ১৯ মে ১৯৮৭) একজন বাংলাদেশি দেওবন্দি ইসলামি পণ্ডিত, রাজনীতিবিদ, শিক্ষাবিদ, লেখক, গবেষক, বাগ্মী, বিতার্কিক ও সমাজ সংস্কারক ছিলেন। তিনি আল জামিয়া আল ইসলামিয়া পটিয়ার শায়খুল হাদিস, নেজামে ইসলাম পার্টির সভাপতি ও আঞ্জুমানে ইত্তেহাদুল মাদারিস বাংলাদেশের মহাসচিব ছিলেন। তিনি ১৯৫৪ সালে পূর্ব বাংলা আইনসভার সদস্য নির্বাচিত হয়েছিলেন। অসাধারণ বাগ্মীতার কারণে তিনি খতিবে আজম বা বড় বক্তা উপাধি পেয়েছিলেন। বাংলাদেশের স্বাধীনতা পরবর্তী তাকে ২২ মাস বিনাবিচারে কারাগারে বন্দী করা হয়েছিল। কারা অভ্যন্তরে কোনোরূপ সহায়ক গ্রন্থের সাহায্য ছাড়াই তিনি ৮ খণ্ডে শানে নবুয়ত  রচনা করেছিলেন। তিনি  বাংলাদেশে স্বাধীন উত্তর ইসলামি রাজনীতির সূচনাকারী ইসলামিক ডেমোক্রেটিক লীগের প্রতিষ্ঠাতা সভাপতি ছিলেন।

Education: Darul Uloom Deoband, Mazahir Uloom, Darul Uloom Hathazari

Source: Wikipedia — https://bn.wikipedia.org/wiki/%E0%A6%9B%E0%A6%BF%E0%A6%A6%E0%A7%8D%E0%A6%A6%E0%A6%BF%E0%A6%95_%E0%A6%86%E0%A6%B9%E0%A6%AE%E0%A6%A6$b$, 'bn', NULL, $b$Ulema, Politician, Writer$b$, $b$Chakaria Upazila$b$, $b$Chakaria Upazila$b$, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Qazi Abdul Alim$b$, DATE '1933-12-31', DATE '2007-08-25', $b$Qazi Abdul Alim (31 December 1933 – 25 August 2007) was a Bangladeshi athlete and sports organiser. He won the Provincial Athletics Championship for nine consecutive years from 1948 to 1956 and athletics meet of Salimullah Muslim Hall at the University of Dhaka for seven consecutive years, from 1950 to 1956. He was awarded Independence Day Award in 1993 by the Government of Bangladesh for his contribution to sports.

Awards: Independence Award
Education: University of Dhaka, University of Oregon

Source: Wikipedia — https://en.wikipedia.org/wiki/Qazi_Abdul_Alim$b$, 'en', NULL, $b$Writer, Athlete$b$, $b$Dhaka$b$, NULL, 'day', 'day');
