INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Qazi Mu'tasim Billah$b$, DATE '1933-06-15', DATE '2013-07-15', $b$Qazi Mu'tasim Billah Bahar (Bengali: কাজী মুতাসিম বিল্লাহ বাহার; 15 June 1933 – 15 July 2013) was a Bangladeshi Islamic scholar, teacher, author and politician. He was the principal of Jamia Shar'iyya Malibagh for over four decades, a former professor at the University of Dhaka and the founding principal of Jamia Islamia Darul Uloom Madania in Jatrabari, Dhaka. He has written many books and articles in the Bengali language and pioneered the introduction of a Bengali-medium among the Qawmi madrasas of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Qazi_Mu'tasim_Billah$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Bayt%20al%20Mukarram.jpg?width=640$b$, $b$Writer$b$, NULL, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$R. C. Majumdar$b$, DATE '1888-12-04', DATE '1980-02-11', $b$Ramesh Chandra Majumdar (known as R. C. Majumdar; 4 December 1888 – 11 February 1980) was an Indian historian and professor. He is regarded as belonging to the nationalist school of Indian historiography. Modern scholars view this brand of historiography as "communalist" or "Hindu nationalist".

Awards: honorary doctor of the University of Calcutta
Education: University of Calcutta, Surendranath College, Presidency University, Ravenshaw University

Source: Wikipedia — https://en.wikipedia.org/wiki/R._C._Majumdar$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/R%20C%20Majumdar.jpg?width=640$b$, $b$Historian, University teacher, Writer$b$, $b$Faridpur District$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Rabindra Kumar Das Gupta$b$, DATE '1915-07-02', DATE '2009-02-03', $b$Rabindra Kumar Das Gupta (11 July 1915 – 3 February 2009) was an Indian scholar of Bengali and English literature and a social and cultural commentator. He was considered by his peers as one of the last scholars with equal command of English and Bengali languages.

Education: Exeter College, University of Calcutta, Scottish Church College

Source: Wikipedia — https://en.wikipedia.org/wiki/Rabindra_Kumar_Das_Gupta$b$, 'en', NULL, $b$Linguist, Writer$b$, $b$Kolkata$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Rabiul Hussain$b$, DATE '1943-01-31', DATE '2019-11-26', $b$Rabiul Hussain (31 January 1943 – 26 November 2019) was a Bangladeshi poet and architect. He was one of the trustees of the Bangladesh Liberation War Museum. He was awarded Bangla Academy Literary Award in 2009 for poetry. In recognition of his contribution to Bengali language and literature, the government of Bangladesh awarded him the country's second highest civilian award Ekushey Padak in 2018.

Awards: Ekushey Padak
Education: Bangladesh University of Engineering and Technology

Source: Wikipedia — https://en.wikipedia.org/wiki/Rabiul_Hussain$b$, 'en', NULL, $b$Architect, Poet, Writer$b$, $b$Shailkupa Upazila$b$, $b$Bangladesh Medical University$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Rafiqul Haque$b$, DATE '1937-01-01', DATE '2021-10-10', $b$Rafiqul Haque (known as Dadu Bhai; 8 January 1937 – 10 October 2021) was a Bangladeshi journalist and poet. He worked for the Daily Jugantor, published in Dhaka, as its feature editor. Earlier in his career, he was the executive editor of the Dainik Rupali, Dainik Janata and also worked for Dainik Azad, Dainik Lal Sabuj and The Bangladesh Observer. Haque was reputed for his rhymes.

Haque was the acting editor of the Kishore Bangla from 1976 to 1983, the only weekly newspaper for children ever published in the Indian sub-continent.

Haque received many awards, including the Bangla Academy Award, Bangladesh Children's Academy Award, Agrani Bank Children's Literature Award, Chandrabati Academy Award, and All India Children's Literature Award.

He died in 2021.

Awards: Bangla Academy Literary Award

Source: Wikipedia — https://en.wikipedia.org/wiki/Rafiqul_Haque$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Rafiqul%20Haque%20Feb%202013.jpg?width=640$b$, $b$Journalist, Poet, Writer$b$, NULL, NULL, 'year', 'day');
