INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Rajendra Lahiri$b$, DATE '1901-06-23', DATE '1927-12-17', $b$Rajendra Nath Lahiri (23 June 1901 — 17 December 1927), known simply as Rajendra Lahiri, was an Indian revolutionary, who was a mastermind behind the Kakori conspiracy and Dakshineshwar bombing. He was an active member of the Hindustan Republican Association, aimed at ousting the British from India.

