INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Ramnath Biswas$b$, DATE '1894-01-13', DATE '1955-11-01', $b$Ramnath Biswas (Bengali: রামনাথ বিশ্বাস, romanized: Ramnath Bishshash; 13 January 1894 – 1 November 1955) was an Indian revolutionary, soldier, globetrotter and travelogue writer. He is known for circumnavigating the globe by bicycle.

