INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Rangalal Sen$b$, DATE '1933-09-24', DATE '2014-02-10', $b$Rangalal Sen (24 September 1933 – 10 February 2014) was a Bangladesh academician and writer. In 2011, he was inducted as the National Professor of Bangladesh.

Education: University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Rangalal_Sen$b$, 'en', NULL, $b$Writer$b$, $b$Maulvi Bazar$b$, $b$Chittagong$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Rashid Karim$b$, DATE '1925-08-14', DATE '2011-11-26', $b$Rashid Karim (14 August 1925 – 26 November 2011) was a Bangladeshi novelist.

Karim completed a BA at Calcutta Islamia College. His family moved to Dhaka after the partition in 1947. He began writing at fourteen and published his first story in 1942. After a long break, Karim resumed writing in 1961, and his first novel, Uttam Purush, earned him the prestigious Adamjee Award. His fame peaked with the publication of his epic novel Amar Jato Glani (1973), and he continued to write and publish regularly thereafter. Karim battled paralysis for nineteen years and died in Dhaka on 26 November 2011.

Awards: Ekushey Padak, Bangla Academy Literary Award
Education: University of Calcutta, Maulana Azad College

Source: Wikipedia — https://en.wikipedia.org/wiki/Rashid_Karim$b$, 'en', NULL, $b$Writer$b$, $b$Kolkata$b$, $b$Dhaka$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Rashid Talukder$b$, DATE '1939-10-24', DATE '2011-10-25', $b$Rashid Talukder (24 October 1939 – 25 October 2011) was a Bangladeshi photojournalist for The Daily Ittefaq, most known for capturing some of the defining images of the genocide during the Bangladesh Liberation War of 1971.

Talukder was a founder of the Bangladesh Photo Journalists' Association. He was awarded the Lifetime Achievement Award at the Chobi Mela, an international photography festival in Dhaka, in 2006, and the 2010 the 'Pioneer Photographer Award' given by National Geographic magazine.

Source: Wikipedia — https://en.wikipedia.org/wiki/Rashid_Talukder$b$, 'en', NULL, $b$Author, Photographer, Journalist, War photographer$b$, $b$Budge Budge$b$, $b$Dhaka$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Rassundari Devi$b$, DATE '1810-01-01', DATE '1900-01-01', $b$Rashsundari Devi (Bengali: রাসসুন্দরী দেবী) (c. 1809–1899) was a Bengali woman who is identified as the author of first full-fledged autobiography in modern Bengali literature. She is among the earliest woman writers in Bengali literature.

Rashsundari Devi was born in Eastern Bengal and was the first Indian woman to write an autobiography and the first Bengali to write an  autobiography. 'Amar Jiban' was the name of her autobiography.

Source: Wikipedia — https://en.wikipedia.org/wiki/Rassundari_Devi$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Rassundari%20Dasi.jpg?width=640$b$, $b$Writer, Autobiographer$b$, $b$Pabna$b$, NULL, 'year', 'year');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Rezaur Rahman$b$, DATE '1945-01-11', DATE '2025-10-26', $b$Rezaur Rahman (11 January 1944 – 26 October 2025) was a Bangladeshi nuclear scientist, entomologist, educator, and writer. He was widely respected for his work in scientific research and for writing popular science and fiction in Bengali. In 2024, he received the Bangla Academy Literary Award for his contributions to science literature.

Awards: Bangla Academy Literary Award

Source: Wikipedia — https://en.wikipedia.org/wiki/Rezaur_Rahman_(scientist)$b$, 'en', NULL, $b$Poet, Literature, Journalist, Writer$b$, NULL, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Riaz Uddin Ahmed$b$, DATE '1945-01-01', DATE '2021-12-25', $b$Riaz Uddin Ahmed (30 November 1945 – 25 December 2021) was a Bangladeshi journalist who was the president of the National Press Club. In 1993, he was awarded the Ekushey Padak, the state's second highest civilian honor, for his outstanding contribution to journalism. He was the editor of News Today. He was an advisor to former Prime Minister of Bangladesh Khaleda Zia.

Education: University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Riaz_Uddin_Ahmed$b$, 'en', NULL, $b$Journalist$b$, NULL, NULL, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Ritwik Ghatak$b$, DATE '1925-11-04', DATE '1976-02-06', $b$Ritwik Kumar Ghatak (Bengali: [rit̪ːik ɡʱɔʈok] ; 4 November 1925 – 6 February 1976) was an Indian film director, screenwriter, actor and playwright. Widely considered as one of the greatest film makers of all time, his works remained largely underrated and ignored during his lifetime. Along with prominent contemporary Bengali filmmakers like Satyajit Ray, Tapan Sinha and Mrinal Sen, his cinema is primarily remembered for its meticulous depiction of social reality, partition and feminism. He won the National Film Award's Rajat Kamal Award for Best Story in 1974 for his Jukti Takko Aar Gappo and Best Director's Award from Bangladesh Cine Journalist's Association for Titash Ekti Nadir Naam. The Government of India honoured him with the Padma Shri for Arts in 1970.

Notable works: Nagarik
Awards: Padma Shri in arts
Education: University of Calcutta, Rajshahi College, Ballygunge Government High School, Rajshahi Collegiate School

Source: Wikipedia — https://en.wikipedia.org/wiki/Ritwik_Ghatak$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Ritwik%20Ghatak%20%28Young%20age%20photo%29.png?width=640$b$, $b$Film director, Film actor, Screenwriter, Film producer, Composer, Writer$b$, $b$Dhaka$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Robert Grant$b$, DATE '1779-01-01', DATE '1838-07-09', $b$Sir Robert Grant, GCH (1779 – 9 July 1838) was a British lawyer and politician. Born in Bengal in 1779, his family relocated to England in 1790.

He studied law at Magdalene College, Cambridge, and in 1807 passed the bar. He became a Commissioner in Bankruptcy. Between 1818 and 1832, he was an elected member of Parliament for several different Burghs.

On 11 August 1829, in Inverness-shire Grant married Margaret Davidson, daughter of Sir David Davidson. They had four children, two daughters and two sons. Grant died in Dapodi, in Poona, India in 1838.

Awards: Knight Grand Cross of the Royal Order of the Welfs
Education: Magdalene College

Source: Wikipedia — https://en.wikipedia.org/wiki/Robert_Grant_(MP)$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Portrait-robert-grant-beechey.jpg?width=640$b$, $b$Politician, Writer, Poet, Hymnwriter, Governor, Lawyer$b$, $b$Bengal$b$, NULL, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Romena Afaz$b$, DATE '1926-12-27', DATE '2003-06-12', $b$Romena Afaz (27 December 1926 – 12 June 2003) was a Bangladeshi adventure-thriller writer. She is notable for her adventure-thriller series Doshyo Bonhur (Robber Bonhur).

