INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$S'adat Ali Akhand$b$, DATE '1899-07-01', DATE '1971-05-12', $b$S'adat Ali Akhand (1 July 1899 – 12 May 1971) was a Bangladeshi essayist and litterateur. His notable books include Itihasher Xahid (1935), Otit O Bortoman (1936), Muhammad bin Qasim (1936), Osman Khan (1936), Dayud Khan (1936), Tero Numberey Panch Bosor (1969) and Onya Din Onya Jiban (1969).

