INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$S. I. M. Nurunnabi Khan$b$, DATE '1942-01-01', DATE '2019-05-22', $b$Shamsul Islam Muhammad Nurunnabi Khan (Bengali: শামসুল ইসলাম মোহাম্মদ নূরুন্নবী খাঁন; 1942 – 22 May 2019) was a Bangladeshi freedom fighter and writer. He was awarded Bir Bikrom for his contribution to the Liberation War of Bangladesh.

Education: Cranfield University

Source: Wikipedia — https://en.wikipedia.org/wiki/S._I._M._Nurunnabi_Khan$b$, 'en', NULL, $b$Writer$b$, NULL, NULL, 'year', 'day');
