INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Samudra Gupta$b$, DATE '1946-06-23', DATE '2008-07-19', $b$Samudra Gupta (born Abdul Mannan; June 23, 1946 – July 19, 2008) was a Bangladeshi poet and journalist. Gupta was a strong critic of both communalism and Islamic fundamentalism, and expressed his opposition to these ideologies within his writings.

Source: Wikipedia — https://en.wikipedia.org/wiki/Samudra_Gupta_(poet)$b$, 'en', NULL, $b$Journalist, Poet$b$, NULL, $b$Bengaluru$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Santosh Gupta$b$, DATE '1925-01-09', DATE '2004-08-06', $b$Santosh Gupta (9 January 1925 – 6 August 2004) was a Bangladeshi journalist and writer. He was awarded Ekushey Padak in 1997 and Independence Day Award in 2015 by the Government of Bangladesh. He wrote sometimes under the pen name Aniruddha.

