INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Santosh Kumar Ghosh$b$, DATE '1920-09-09', DATE '1985-02-26', $b$Santosh Kumar Ghosh (9 September 1920 – 26 February 1985) was an Indian Bengali litterateur and a journalist of repute.

