INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Sarat Chandra Das$b$, DATE '1849-07-18', DATE '1917-01-05', $b$Sarat Chandra Das (Bengali: শরৎচন্দ্র দাশ) (18 July 1849 – 5 January 1917) was an Indian scholar of Tibetan language and culture most noted for his two journeys to Tibet in 1879 and in 1881–1882.

