INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Selina Parvin$b$, DATE '1931-03-31', DATE '1971-12-14', $b$Selina Parvin (31 March 1931 – 14 December 1971) was a Bangladeshi journalist and poet. She is one of the intellectual martyrs killed by Al-Badr on 14 December, immediately before the victory after the 9-month-long war of independence of Bangladesh in 1971. This day later came to be commemorated as the intellectual martyr day.  As a journalist she used to work for Weekly Begum, Weekly Lalana and Shilalipi. She was buried in Azimpur Graveyard on 18 December 1971.

Source: Wikipedia — https://en.wikipedia.org/wiki/Selina_Parvin$b$, 'en', NULL, $b$Journalist, Poet$b$, NULL, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Serajuddin Hossain$b$, DATE '1929-03-01', DATE '1971-12-10', $b$Serajuddin Hossain (1 March 1929 – 10 December 1971) was a prominent Bangladeshi journalist. He was the news and executive editor of The Daily Ittefaq. He was captured from his residence by the Pakistan army with the help of Al-Badr and Razakars. He was not only a prominent journalist, but was also considered to be a good writer and translator. He was very close to Sheikh Mujibur Rahman. He was the first to introduce investigative reporting into Bangla newspaper. During the Bangladesh Liberation War of 1971, the country was occupied by the Pakistani army. During this time, Serajuddin Hossain wrote in the newspaper on behalf of the liberation war, and secretly helped the freedom fighters.

Awards: Ekushey Padak
Education: University of Calcutta, Maulana Azad College

Source: Wikipedia — https://en.wikipedia.org/wiki/Serajuddin_Hossain$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Serajuddin%20Hossain1.JPG?width=640$b$, $b$Journalist, Writer$b$, NULL, $b$Dhaka$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Serajur Rahman$b$, DATE '1934-01-01', DATE '2015-06-01', $b$A. N. M. Serajur Rahman (1934 – 1 June 2015) was a British journalist of Bengali Muslim descent and broadcaster. From 1960 to 1994, he worked for BBC World Service, and was the deputy chief of BBC Bangla Service before retirement. He remains a contentious figure in journalism due to his disputed claim about the death toll in Bangladesh's 1971 Liberation War, asserting that the number was closer to 300,000 rather than the widely cited figure of 3 million.

Awards: Ekushey Padak
Education: Dhaka College

Source: Wikipedia — https://en.wikipedia.org/wiki/Serajur_Rahman$b$, 'en', NULL, $b$Journalist, Author$b$, $b$Noakhali District$b$, $b$Royal Free Hospital$b$, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shah Abdul Hannan$b$, DATE '1939-01-01', DATE '2021-06-02', $b$Shah Abdul Hannan (Bengali: শাহ আবদুল হান্নান; 23 September 1939 – 2 June 2021) was a Bangladeshi Islamic philosopher, writer, economist, educator and media personality. He served as the deputy governor of the Bangladesh Bank and chairman of the National Board of Revenue. He was the founding vice chancellor of Darul Ihsan University, North South University, chairman of the Islamic Economics Research Bureau, and the director of Islami Bank Bangladesh Ltd.

Education: University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Shah_Abdul_Hannan$b$, 'en', NULL, $b$Writer, Economist, Researcher$b$, $b$Mymensingh$b$, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shah Abul Hasnat Mohammad Ismail$b$, NULL, DATE '1984-01-01', $b$Shah Abul Hasnat Mohammad Ismail is a Bangladeshi writer posthumously awarded the Independence Award, the highest civilian award of Bangladesh, in 1984. He wrote a well-known book on sex education in Bengali.

