Source: Wikipedia — https://en.wikipedia.org/wiki/Shah_Abul_Hasnat_Mohammad_Ismail$b$, 'en', NULL, $b$Writer$b$, NULL, NULL, 'day', 'year');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shah Alamgir$b$, DATE '1956-01-01', DATE '2019-02-28', $b$Shah Alamgir (died 28 February 2019) was a Bangladeshi journalist. He served as the Director General of Press Institute of Bangladesh. He joined the post on 7 July 2013. Before joining PIB, he worked as a journalist.

