INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shahadat Chowdhury$b$, DATE '1943-07-28', DATE '2005-11-29', $b$Shahadat Chowdhury (28 July 1943 – 29 November 2005) was a Bangladeshi journalist and editor of several news magazines. He served as the editor of Weekly Bichitra from 1972 until its publication was ceased in 1997. He then served as the editor of Shaptahik 2000 and Anandadhara.

In 1993, Chowdhury was awarded the Ekushey Padak, the state's second highest civilian honor, for his outstanding contribution to journalism.

Source: Wikipedia — https://en.wikipedia.org/wiki/Shahadat_Chowdhury$b$, 'en', NULL, $b$Journalist$b$, $b$Khulna$b$, $b$Dhaka$b$, 'day', 'day');
