INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shahidul Haque Khan$b$, DATE '1948-01-01', DATE '2023-04-19', $b$Shahidul Haque Khan (11 November 1948 – 19 April 2023) was a Bangladeshi film writer, director and lyricist. He won Bangladesh National Film Award for Best Lyrics for the film Chhutir Phande (1990).

Khan died from cancer on 19 April 2023, at the age of 74.

Source: Wikipedia — https://en.wikipedia.org/wiki/Shahidul_Haque_Khan$b$, 'en', NULL, $b$Writer$b$, $b$Munshiganj District$b$, $b$Dhaka$b$, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shamsuddin Qasemi$b$, DATE '1935-03-05', DATE '1996-10-19', $b$Shamsuddin Qasemi (Bengali: শামসুদ্দীন কাসেমী; 5 March 1935 – 19 October 1996) was a Bangladeshi Islamic scholar, politician, author and educationist. He was the founding president of the Khatme Nabuwwat Andolan Council, former secretary-general of Jamiat Ulema-e-Islam Bangladesh, former principal of Jamia Madania Chittagong and Jamia Hussainia Arzabad, and the founding chief-editor of the monthly Paygam-e-Haqq and weekly Jamiat magazines. He is also noted for his contributions during the Bangladesh Liberation War of 1971.

Source: Wikipedia — https://en.wikipedia.org/wiki/Shamsuddin_Qasemi$b$, 'en', NULL, $b$Writer$b$, NULL, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shamsunnahar Mahmud$b$, DATE '1908-01-01', DATE '1964-04-10', $b$Shamsunnahar Mahmud (c. 1908 — April 10, 1964) was a writer, politician and educator in Bengal during the early 20th century. She was a leader of the women's rights movement in Bengal pioneered by Begum Rokeya. Shamsunnahar Hall of the University of Dhaka and University of Chittagong was named after her.

Awards: Begum Rokeya Padak, Independence Award, Honorary Fellow of Bangla Academy
Education: University of Calcutta, Dr. Khastagir Government Girls' School

Source: Wikipedia — https://en.wikipedia.org/wiki/Shamsunnahar_Mahmud$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Corner%20stone%20pf%20Shamsun%20nahar%20Mahmud%20%28cropped%29.jpg?width=640$b$, $b$Politician, Writer, Travel writer$b$, $b$Feni District$b$, $b$Dhaka$b$, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shankha Ghosh$b$, DATE '1932-02-05', DATE '2021-04-21', $b$Sankha Ghosh (born Chittapriya Ghosh; 5 February 1932 – 21 April 2021) was an Indian poet and literary critic. He was born in Chandpur District of the then Bengal Presidency, present day Bangladesh. His ancestral home was at Banaripara Upazila in Barisal District. He spent his childhood and adolescence in Ishwardi Upazila of Pabna District, which was his father's workplace.

Ghosh passed matriculation from Chandraprabha Vidyapitha, Pabna. He got his undergraduate degree in Arts in Bengali from Presidency College, Kolkata in 1951 and subsequently his master's degree from the University of Calcutta in the year 1954.

Acclaimed in India, his work lacks global recognition due to poor English translations.

Notable works: Babarer Prarthona
Awards: Sahitya Akademi Award in Bengali, Padma Bhushan, Jnanpith Award, Saraswati Samman, Gangadhar National Award, Rabindra Puraskar
Education: University of Calcutta, Presidency University

Source: Wikipedia — https://en.wikipedia.org/wiki/Shankha_Ghosh$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Sankha%20Ghosh%20-%20Kolkata%202011-05-09%202833.JPG?width=640$b$, $b$Poet, Literary critic, Writer$b$, $b$Chandpur District$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shantanu Kaiser$b$, DATE '1954-12-30', DATE '2017-04-11', $b$Shantanu Kaiser (30 December 1954 – 11 April 2017) was a Bangladeshi poet and essayist. He was awarded Bangla Academy Literary Award (2014) in the essay category.

Awards: Bangla Academy Literary Award
Education: University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Shantanu_Kaiser$b$, 'en', NULL, $b$Writer, Poet$b$, $b$Faridganj Upazila$b$, $b$Dhaka$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shanti Ranjan Bhattacharya$b$, DATE '1930-09-29', DATE '1993-09-15', $b$Shanti Ranjan Bhattacharya (24 September 1930 – 15 September 1993) was a Bengali scholar and writer known for his contributions to Urdu literature. He explored the linguistic and literary connections between Urdu and Bengali, and documented the role of Bengali Hindus in the development of Urdu. His seminal book Bengali Hinduon ki Urdu Khidmaat (The Contributions of Bengali Hindus to Urdu) earned him the Rabindra Puraskar awarded by the Government of West Bengal in 1966.

Awards: Rabindra Puraskar

Source: Wikipedia — https://en.wikipedia.org/wiki/Shanti_Ranjan_Bhattacharya$b$, 'en', NULL, $b$Scholar, Writer$b$, $b$Faridpur District$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shashibhusan Dasgupta$b$, DATE '1911-01-01', DATE '1964-07-21', $b$Shashibhusan Dasgupta, or Shashi Bhushan Dasgupta, Shashibhusan and Shashi Bhusan Das Gupta (17 March 1911 – 21 July 1964) was a Bengali scholar of philosophy, languages, literature (particularly Bengali literature), literary critic, author and theologian.

Dasgupta was born in Chandrahar Village in modern Barisal Division, South-Central Bangladesh. He obtained his IA from B M College, Barisal, and his BA (Hons) in Philosophy from Scottish Church College, Kolkata, West Bengal, India. His MA in Bengali Language and Literature from Calcutta University in 1935, and he subsequently joined Calcutta University's Bengali Department as a Researcher. Winning the 1937 Premchand Roychand Scholarship due to his scholarship contributions, Dasgupta was appointed a lecturer in the Bengali Department and received his PhD in that department in 1939.

Dasgupta's chief opus is the identification of Indian spiritual meditation forms and demonstration of their relationship to Tantric Buddhism, to Saivite, Sakta and Vaishnava religious philosophies, and to Bengali literature. He won the 1961 Sahitya Akademi Award for his work Bharater Shakti-Sadhana O Shakta Sahitya.

Dasgupta had authored novels, plays, poems and children's books. Some editions of his works are published posthumously or in recently updated versions, and their exact or cited titles in English depend on the language variants being transliterated.

Awards: Sahitya Akademi Award in Bengali
Education: University of Calcutta, Scottish Church College

Source: Wikipedia — https://en.wikipedia.org/wiki/Shashibhusan_Dasgupta$b$, 'en', NULL, $b$Academic, Writer, Essayist, Playwright, Poet$b$, $b$Chandrahar$b$, $b$Kolkata$b$, 'year', 'day');
