INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Shyamal Gangapadhyay$b$, DATE '1933-03-25', DATE '2001-09-24', $b$Shyamal Gangapadhyay (25 March 1933 – 24 September 2001; Bengali: শ্যামল গঙ্গাপাধ্যায়) was a Bengali novelist, short story writer and editor born at Khulna (Present day Bangladesh). During Partition of India he and his family of 6 brothers, 1 sister, and his parents migrated to India as refugees. The immense toll of the forced migration on the family led to one of his brothers to commit suicide at his twenties. The financial and personal struggle of these years shaped Shyamal's literary landscape.

He received Sahitya Academy Award in 1993 for the novel of Shahjada Darasukoh, based on the life of Mughal Prince Dara Shukoh. He also wrote the story 'Vasco Da Gamar Bhaipo' and 'Parostri'.

Awards: Sahitya Akademi Award
Education: University of Calcutta

Source: Wikipedia — https://en.wikipedia.org/wiki/Shyamal_Gangapadhyay$b$, 'en', NULL, $b$Writer$b$, $b$Khulna$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Sibnarayan Ray$b$, DATE '1921-01-20', DATE '2008-02-26', $b$Sibnarayan Ray (20 January 1921 – 26 February 2008) was an Indian thinker, educationist, philosopher, and literary critic who wrote in the Bengali language. A radical humanist, he is widely reputed for his works on Marxist-revolutionary Manabendra Nath Roy, and famous polymath Bertrand Russell, commenting on Ray, once said that "... Sibnarayan Ray stands for a point of view which I consider important in every part of the world. ... His writings ably represents a more reasonable point of view than that of most writers of our time."

Awards: Sahitya Akademi Award
Education: University of Calcutta

Source: Wikipedia — https://en.wikipedia.org/wiki/Sibnarayan_Ray$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Sibnarayan%20Ray%202006.jpg?width=640$b$, $b$Philosopher, Poet, Writer, Academic, Literary scholar$b$, $b$Kolkata$b$, $b$Santiniketan$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Sikdar Aminul Haq$b$, DATE '1942-12-06', DATE '2003-05-17', $b$Sikdar Aminul Haq (Bengali: সিকদার আমিনুল হক; 6 December 1942 – 17 May 2003) was a Bangladeshi poet. In recognition of his contribution in language and literature, the government of Bangladesh posthumously awarded him the country's second highest civilian award Ekushey Padak in 2020.

