INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Sree Parabat$b$, DATE '1927-01-01', DATE '2010-11-02', $b$Sree Parabat or Sri Parabat (1 January 1927 – 2 November 2010) was a Bengali-language writer from Kolkata, India, known mainly for his historical novels.

