INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Syed Abul Fazal Sultan Ahmad$b$, DATE '1909-02-25', DATE '1984-03-28', $b$Syed Abul Fazal Sultan Ahmad (Bengali: সৈয়দ আবুল ফজল সুলতান আহমদ; 1909–1984), also known as Chandrapuri according to his birthplace, was a Bangladeshi Sufi saint, spiritual leader and Islamic scholar. He is most widely recognized as the founder of Chandrapara Pak Darbar Sharif in the Faridpur district and as the spiritual guide (Murshīd) of the late Syed Mahbub E Khoda Dewanbagi, the founder of Dewanbag Sharif.

