INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Tarasankar Bandyopadhyay$b$, DATE '1898-07-23', DATE '1971-09-14', $b$Tarasankar Bandyopadhyay (23 July 1898 – 14 September 1971) was an Indian novelist who wrote in the Bengali language. He wrote 65 novels, 53-story-books, 12 plays, 4 essay-books, 4 autobiographies, 2 travel stories and composed several songs. He was awarded Rabindra Puraskar, Sahitya Akademi Award, Jnanpith Award, Padma Shri and Padma Bhushan. He was nominated for Nobel Prize in Literature in 1971 and posthumously nominated in 1972.

Notable works: Hansuli Banker Upakatha
Awards: Sahitya Akademi Award, Jnanpith Award, Padma Bhushan, Padma Shri in literature and education
Education: St. Xavier's College, Kolkata, Asutosh College

