INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Tofazzal Hossain Manik Miah$b$, DATE '1911-01-01', DATE '1969-06-01', $b$Tofazzal Hossain, popularly known as Manik Miah (c. 1911 – 1 June 1969), was a Pakistani Bengali journalist and politician. He served as the founding editor of The Daily Ittefaq. He wrote the editorial Rajnoitik Moncho ("The Political Stage"). Most of his newspaper's journalists were considered leftist, as Miah followed the pattern of Awami League. According to journalist and editor of Shongbad Bozlur Rahman, Awami activists followed his editorial more than any actual decision of a meeting. He was a close associate of Huseyn Shaheed Suhrawardy and a mentor to Sheikh Mujibur Rahman.

Miah wrote his political columns in Bengali. He was equally prolific in his English renderings. Miah, who was popularly known for his powerful political column in The Daily Ittefaq (founded by Abdul Hamid Khan Bhashani and Yar Mohammad Khan) under the pen-name 'Musafir', dedicated his entire life for the cause of emancipation of the people in the then East Pakistan (now Bangladesh) and establishing the democracy. Yar Mohammad Khan invited Miah, who was working at that time as a journalist, at Calcutta and made him the editor of The Daily Ittefaq.

Awards: Ekushey Padak in Journalism

Source: Wikipedia — https://en.wikipedia.org/wiki/Tofazzal_Hossain_Manik_Miah$b$, 'en', NULL, $b$Author, Journalist, Politician$b$, $b$Pirojpur District$b$, $b$Dhaka$b$, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Toufique Imrose Khalidi$b$, NULL, DATE '2026-10-02', $b$Toufique Imrose Khalidi (Bengali: তৌফিক ইমরোজ খালিদী; 14 June 1967 – 2 October 2026) was a Bangladeshi journalist, editor, media businessman, and the owner and editor-in-chief of bdnews24.com.

Source: Wikipedia — https://en.wikipedia.org/wiki/Toufique_Imrose_Khalidi$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Toufique%20Imrose%20Khalidi.jpg?width=640$b$, $b$Journalist$b$, $b$Bangladesh$b$, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Trailokyanath Chakravarty$b$, DATE '1889-01-01', DATE '1970-08-09', $b$Trailokyanath Chakraborty (2 August 1889 – 9 August 1970) was a British Indian independence activist and later East Pakistani politician. He led and worked with other freedom fighters. He lived for 80 years, spending 30 years in jail. Some of his time in jail was in Bangladesh, which was under Pakistani control, after the partition of India into India and Pakistan.  After independence in 1947, he became a politician and parliamentary member from East Pakistan (present-day Bangladesh). In spite of being a freedom fighter and spending much of his life in hiding, he had a strong influence in the family of his brothers, education of grandchildren and their marriage decisions. He inspired many female grandchildren to get higher educational degrees. He was never married.

Source: Wikipedia — https://en.wikipedia.org/wiki/Trailokyanath_Chakravarty$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Maharaj%20Trailokyanath%20Chakraborty.jpg?width=640$b$, $b$Revolutionary, Writer$b$, $b$Mymensingh$b$, NULL, 'year', 'day');
