INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Tushar Kanti Ghosh$b$, DATE '1898-09-21', DATE '1994-08-29', $b$Tushar Kanti Ghosh (21 September 1898 – 29 August 1994) was an Indian journalist and writer. For sixty years, until shortly before his death, Ghosh was the editor of the English-language newspaper Amrita Bazar Patrika in Kolkata. He also served as the leader of prominent journalism organizations such as the International Press Institute and the Commonwealth Press Union. Ghosh was known as the "grand old man of Indian journalism" and "the dean of Indian journalism" for his contributions to the country's free press.

Awards: Padma Bhushan
Education: Bangabasi College

