INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Ubaidul Haq$b$, DATE '1928-05-02', DATE '2007-10-06', $b$Ubaidul Haq (Bengali: উবায়দুল হক; 2 May 1928 – 6 October 2007), also spelt Obaidul Haq (Bengali: ওবাইবদুল হক), was a Bangladeshi teacher, muhaddith, mufassir and writer. He was the former khatib of the national mosque of Bangladesh.

