INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Ullaskar Dutta$b$, DATE '1885-04-16', DATE '1965-05-17', $b$Ullaskar Dutta (16 April 1885 – 17 May 1965) was an Indian revolutionary associated with Anushilan Samiti and Jugantar of Bengal, and was a close associate of Barindra Ghosh. He was the principal bomb maker of the Jugantar group until Hemchandra Kanungo returned from Paris learning political theory and explosive chemistry.

Education: Presidency University, University of London

Source: Wikipedia — https://en.wikipedia.org/wiki/Ullaskar_Dutta$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Ullaskar%20Dutta.jpg?width=640$b$, $b$Revolutionary, Writer$b$, $b$Brahmanbaria District$b$, $b$Silchar$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Upendrakishore Ray Chowdhury$b$, DATE '1863-05-10', DATE '1915-12-20', $b$Upendrakishore Ray Chowdhury (Bengali: [upend̪ɾokiʃoɾ rae̯ t͡ʃou̯d̪ʱuɾi] ; 12 May 1863 – 20 December 1915) was a Bengali writer, painter and entrepreneur. He was the son-in-law of reformer Dwarkanath Ganguly.

Education: University of Calcutta, Vidyasagar College, Mymensingh Zilla School

Source: Wikipedia — https://en.wikipedia.org/wiki/Upendrakishore_Ray_Chowdhury$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Upendrokishor-ray.gif?width=640$b$, $b$Writer, Illustrator, Children's writer, Playwright, Short story writer, Painter$b$, $b$Mymensingh District$b$, $b$Giridih$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Upendranath Bhattacharya$b$, DATE '1899-01-01', DATE '1970-01-01', $b$Upendranath Bhattacharya is an Indian Bengali writer.

