INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Utpal Dutt$b$, DATE '1929-03-29', DATE '1993-08-19', $b$Utpal Dutt (; 29 March 1929 – 19 August 1993) was an Indian actor, director, and writer-playwright. He was primarily an actor in Bengali theatre, where he became a pioneering figure in Modern Indian theatre, when he founded the "Little Theatre Group" in 1949. This group enacted many English, Shakespearean and Brecht plays, in a period now known as the "Epic theatre" period, before it immersed itself completely in highly political and radical theatre. His plays became an apt vehicle for the expression of his Marxist ideologies, visible in socio-political plays such as Kallol (1965), Manusher Adhikar, Louha Manob (1964), Tiner Toloar and Maha-Bidroha. He also acted in over 100 Bengali and Hindi films in a career spanning 40 years, and remains most known for his roles in films such as Mrinal Sen’s Bhuvan Shome (1969), Satyajit Ray’s Agantuk (1991), Gautam Ghose’s Padma Nadir Majhi (1992) and Hrishikesh Mukherjee's breezy Hindi comedies such as Gol Maal (1979) and Rang Birangi (1983). He also did the role of a sculptor, Sir Digindra Narayan, in the episode Seemant Heera of Byomkesh Bakshi (TV series) on Doordarshan in 1993, shortly before his death.

He received National Film Award for Best Actor in 1970 and three Filmfare Best Comedian Awards. In 1990, the Sangeet Natak Akademi, India's National Academy of Music, Dance and Theatre, awarded him its highest award, the Sangeet Natak Akademi Fellowship for lifetime contribution to theatre.

Awards: Sangeet Natak Akademi Award, Filmfare Awards, National Film Award for Best Actor, Filmfare Award for Best Performance in a Comic Role, Fellow of the Sangeet Natak Akademi
Education: University of Calcutta, St. Xavier's College, Kolkata, St. Xavier's Collegiate School, St. Lawrence High School, Kolkata

Source: Wikipedia — https://en.wikipedia.org/wiki/Utpal_Dutt$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Utpal%20Dutt%202013%20stamp%20of%20India.jpg?width=640$b$, $b$Film director, Actor, Writer, Screenwriter, Playwright, Director$b$, $b$Barishal$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Utpalendu Chakrabarty$b$, DATE '1948-01-01', DATE '2024-08-20', $b$Utpalendu Chakrabarty (1948 – 20 August 2024) was an Indian filmmaker based in Kolkata.

Awards: National Film Award for Best Direction
Education: University of Calcutta, Scottish Church College

Source: Wikipedia — https://en.wikipedia.org/wiki/Utpalendu_Chakrabarty$b$, 'en', NULL, $b$Film director, Writer, Screenwriter, Musician$b$, $b$Kolkata$b$, $b$Kolkata$b$, 'year', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Vivekananda Mukhopadhyaya$b$, DATE '1904-07-31', DATE '1993-03-20', $b$Vibekananda Mukhopadhyay (Bengali: বিবেকানন্দ মুখোপাধ্যায়) was an Indian Bengali journalist and author. He is best known for Dwitiya Mahajuddher Itihas (দ্বিতীয় মহাযুদ্ধের ইতিহাস,) a three volume book Indian view of World War II. As an activist, he was deeply involved in all the national and international movements of his time. The Government of India awarded him Padma Bhushan, the third highest Indian civilian award, in 1970.

Awards: Padma Bhushan

Source: Wikipedia — https://en.wikipedia.org/wiki/Vivekananda_Mukhopadhyaya$b$, 'en', NULL, $b$Writer$b$, $b$Madaripur$b$, $b$Kolkata$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Waheedul Haq$b$, DATE '1933-03-16', DATE '2007-01-27', $b$Waheedul Haq (16 March 1933 – 27 January 2007) was a journalist, writer, and musicologist of Tagore songs. He was awarded Ekushey Padak for music in 2008 and  Independence Day Award for culture in 2010 by the government of Bangladesh.

Awards: Ekushey Padak, Independence Award
Education: Dhaka College, University of Dhaka

Source: Wikipedia — https://en.wikipedia.org/wiki/Waheedul_Haq$b$, 'en', NULL, $b$Writer$b$, $b$Keraniganj Upazila$b$, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Wali Gandhi$b$, DATE '1907-03-01', DATE '1978-08-03', $b$Mohammad Waliullah (15 November 1904–3 August 1978), more commonly known as Wali Gandhi (Bengali: ওয়ালি গান্ধী), was a Bangladeshi journalist, writer, and political activist. He was known for his involvement in the Anti-British civil disobedience movement in his early life and later for his long career in journalism and government service in East Pakistan (present-day Bangladesh).

Source: Wikipedia — https://en.wikipedia.org/wiki/Wali_Gandhi$b$, 'en', NULL, $b$Journalist$b$, NULL, NULL, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$William Beveridge$b$, DATE '1879-03-05', DATE '1963-03-16', $b$William Henry Beveridge, 1st Baron Beveridge,  (5 March 1879 – 16 March 1963) was a British economist, eugenicist and Liberal politician who played a central role in designing the British welfare state. His 1942 report Social Insurance and Allied Services (known as the Beveridge Report) served as the basis for the welfare state put in place by the Labour government elected in 1945.

He built his career as an expert on unemployment insurance. He served on the Board of Trade as Director of the newly created labour exchanges, and later as Permanent Secretary of the Ministry of Food. He was Director of the London School of Economics and Political Science from 1919 until 1937, when he was elected Master of University College, Oxford.

Beveridge published widely on unemployment and social security, his most notable works being: Unemployment: A Problem of Industry (1909), Planning Under Socialism (1936), Full Employment in a Free Society (1944), Pillars of Security (1943), Power and Influence (1953) and A Defence of Free Learning (1959). He was elected in the 1944 Berwick-upon-Tweed by-election as a Liberal MP. Following his defeat in the 1945 general election, he was elevated to the House of Lords where he served as the leader of the Liberal peers.

Awards: Knight Commander of the Order of the Bath, honorary doctor of the University of Bordeaux, honorary doctor of the University of New Zealand, doctor honoris causa from the University of Paris
Education: Balliol College, University College, Oxford, Charterhouse School

Source: Wikipedia — https://en.wikipedia.org/wiki/William_Beveridge$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/William-Henry-Beveridge-1st-Baron-Beveridge.jpg?width=640$b$, $b$Economist, Politician, Statistician, Writer, Political economist$b$, $b$Rangpur$b$, $b$Oxford$b$, 'day', 'day');
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$William Wright$b$, DATE '1830-01-17', DATE '1889-05-22', $b$William Wright (17 January 1830 – 22 May 1889) was a famous English Orientalist, and Professor of Arabic in the University of Cambridge.  Many of his works on Syriac literature are still in print and of considerable scholarly value, especially the catalogues of the holdings of the British Library and Cambridge University Library. A Grammar of The Arabic Language, often simply known as Wright's Grammar, continues to be a popular book with students of Arabic. Wright is also remembered for the Short history of Syriac literature.

Awards: Pour le Mérite for Sciences and Arts order
Education: University of St Andrews

Source: Wikipedia — https://en.wikipedia.org/wiki/William_Wright_(orientalist)$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/William%20Wright%20orientalist%20bust.jpg?width=640$b$, $b$Writer, Orientalist, University teacher, Translator, Philologist, Church historian, Semitist$b$, $b$Bengal$b$, $b$Cambridge$b$, 'day', 'day');
