INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Zia Haider$b$, DATE '1936-11-18', DATE '2008-09-02', $b$Sheikh Faisal Abdur Rouf Mohammad Ziauddin Haider (known as Zia Haider; 18 November 1936 – 2 September 2008) was a Bangladeshi writer, poet, playwright, translator and academic. He was the founder president of Nagorik Natya Sampradaya and founder of the Bangladesh Institute of Theater Arts. He wrote seven poems, four plays and translated several plays. He was awarded Ekushey Padak by the Government of Bangladesh in 2001 and Bangla Academy Literary Award in 1977.

Awards: Ekushey Padak
Education: University of Dhaka, Rajshahi College

Source: Wikipedia — https://en.wikipedia.org/wiki/Zia_Haider$b$, 'en', NULL, $b$Poet, Writer$b$, $b$Pabna District$b$, NULL, 'day', 'day');
