INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Zulfikar Haidar$b$, DATE '1899-11-19', DATE '1987-04-23', $b$Zulfikar Haidar (Bengali: জুলফিকার হায়দর; 19 November 1899 – 23 April 1987) was a Bangladeshi poet. For his Islamic writings, the Government of Pakistan gave him the title Sitara-e-Khidmat. He was also honored by the People's Republic of Bangladesh with the Ekushey Padak in 1978.

